// generated by scripts/build-extra-exercises.mjs — do not edit
// Russian steps for the rows in lib/exercises-extra.js (machine draft, same overlay as the names).
export default {"fe_7ee918c7":["Лягте на спину, вытянув одну ногу прямо перед собой.","Другой ногой согните бедро и колено под углом 90 градусов. При необходимости вы можете обхватить ногу руками. Это будет ваше исходное положение.","Вытяните ногу прямо в воздух, ненадолго задержавшись в верхней точке. Верните ногу в исходное положение.","Повторите упражнение 10-20 раз, а затем переключитесь на другую ногу."],"fe_6a412386":["Лягте лицом вниз, положив одну ногу на поролоновый валик.","Поверните ногу так, чтобы поролоновый валик касался внутренней поверхности бедра. Перенесите на поролоновый валик максимально возможный вес.","Стараясь расслабить мышцы внутренней поверхности бедра, перекатитесь по пенопласту между бедром и коленом, удерживая точки напряжения в течение 10-30 секунд. Повторите упражнение с другой ногой."],"fe_93c058e5":["Лягте на спину, подняв ноги к потолку.","Попросите партнера держать вас за ступни или лодыжки. Отведите ноги как можно дальше. Это будет ваше исходное положение.","Попытайтесь сжать ноги вместе в течение 10 или более секунд, пока ваш партнер не помешает вам это сделать.","Теперь расслабьте мышцы ног, пока ваш партнер раздвигает ваши ступни, растягиваясь настолько, насколько это удобно для вас. Обязательно сообщите своему партнеру, когда растяжка будет достаточной, чтобы предотвратить перенапряжение или травму."],"fe_145fc5c5":["Примите удобную позу, поставив одну ногу немного впереди другой.","Начните с отталкивания передней ногой, поднимая противоположное колено вперед и как можно выше, прежде чем приземлиться. Старайтесь преодолевать как можно большее расстояние в каждую сторону за каждый прыжок.","Возможно, будет полезно провести линию на земле, чтобы измерить расстояние от края до края.","Повторите то же самое с другой ногой."],"fe_9ed54def":["В положении стоя держите пару гантелей по бокам от себя.","Слегка согнув локти, поднимите вес прямо перед собой до уровня плеч, не раскачиваясь и не помогая корпусом.","Верните гантели на свою сторону.","При следующем повторении поднимите гантели в стороны, разведя их в стороны примерно на высоту плеч.","Верните гантели в исходное положение и продолжайте чередовать движения вперед и в сторону."],"fe_83ba823f":["Из положения лежа согните ноги в коленях и поставьте ступни на пол.","Положите лодыжку одной ноги на колено другой.","Возьмитесь за бедро или колено нижней ноги и подтяните обе ноги к груди. Расслабьте шею и плечи. Задержитесь на 10-20 секунд, а затем поменяйтесь сторонами."],"fe_d869346a":["Начните с положения сидя на полу, согнув ноги и поставив ступни на пол.","Используя мышечный валик или скалку, надавите на мышцы с внешней стороны голеней. Двигайтесь от области чуть ниже колена к области чуть выше лодыжки, задерживаясь в точках напряжения на 10-30 секунд. Повторите упражнение с другой ногой."],"fe_a1a83fa2":["Встаньте и вытяните прямые руки в стороны. Руки должны быть параллельны полу и перпендикулярны (под углом 90 градусов) вашему туловищу. Это будет ваше исходное положение.","Медленно начинайте описывать круги диаметром около 1 фута каждой вытянутой рукой. При выполнении движения дышите нормально.","Продолжайте круговые движения вытянутыми руками в течение примерно десяти секунд. Затем повторите движение в обратном направлении."],"fe_96c2542c":["Такой тренажёр эффективен для развития силы для атласских камней тем, у кого нет самих камней; обычно его делают из обрезков грифа или толстой трубы.","Начните с навешивания нужного веса. Встаньте над весом, обхватив снаряд руками и наклонившись в тазобедренных суставах.","Тяните вес вверх, разгибаясь в тазобедренных суставах, пока он не пройдёт колени. Когда вес пройдёт колени, можно принять его на бёдра: отсесть назад и плотно прижать его к груди.","Завершите движение разгибанием в тазобедренных суставах и коленях, поднимая вес как можно выше. Вес можно возвращать на бёдра или на пол для следующих повторений."],"fe_e14c40b0":["Начните с атласским камнем между стопами. Наклонитесь в тазобедренных суставах и обхватите камень руками вертикально, стараясь завести пальцы под него. У многих камней снизу есть небольшая плоская часть, которая упрощает удержание.","Прижимая камень к корпусу, отталкиваясь задней частью стоп, оторвите камень от пола.","Когда камень пройдёт колени, примите его на бёдра: отсесть назад и положить камень на бёдра.","Сядьте низко, подняв камень высоко на грудь, и перенесите хват поверх камня. Встаньте, толкаясь тазом. Сократите дистанцию до помоста и, отклоняясь назад, разгибайтесь в тазобедренных суставах, чтобы поднять камень как можно выше."],"fe_3b9c3300":["Подойдите к грифу так, чтобы он был по центру стоп. Стопы примерно на ширине таза. Наклонитесь в тазобедренных суставах и возьмитесь за гриф на ширине плеч, разведя лопатки. Обычно используется разнохват.","Когда стопы и хват установлены, сделайте глубокий вдох, опустите таз и согните колени, пока голени не коснутся грифа. Смотрите вперёд, грудь поднята, спина прогнута — начинайте тянуть вес вверх, отталкиваясь пятками.","После того как гриф пройдёт колени, энергично тяните его к себе, сводя лопатки и подавая таз вперёд к грифу.","Опустите штангу, наклоняясь в тазобедренных суставах и направляя её к полу."],"fe_36f82b2e":["Обведите ленту вокруг неподвижной стойки, как у стойки для приседаний.","Возьмите ленту за ручки и отойдите назад, чтобы увеличить натяжение ленты.","Вытяните и поднимите прямые руки перед собой. Совет: Ваши руки должны быть прямыми и параллельными полу, но при этом перпендикулярными туловищу. Ноги должны твердо стоять на полу, расставленные на ширине плеч. Это будет ваше исходное положение.","На выдохе разведите руки в стороны и назад. Держите руки вытянутыми и параллельными полу. Продолжайте движение, пока руки не будут разведены в стороны.","После паузы на вдохе вернитесь в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_5cf97810":["Загрузите сани нужным весом и прикрепите канат или ремни, за которые можно держаться.","Начните упражнение, двигаясь спиной вперёд на заданную дистанцию. Отклонившись назад, шагайте короткими шагами, разгибаясь в ногах, чтобы двигаться как можно быстрее."],"fe_600d2dda":["Это упражнение лучше всего выполнять с партнером. Если у вас нет партнера, мяч можно подбрасывать и поднимать или бросать его о стену.","Встаньте на расстоянии нескольких метров от партнера, так, чтобы они оба смотрели в одном направлении. Зажмите мяч между ног.","Присядьте на корточки, а затем с усилием измените направление движения, полностью выпрямляясь, и перебросьте мяч через голову своему партнеру.","Затем ваш партнер может перекатить мяч обратно к вам. Повторите упражнение желаемое количество раз."],"fe_355b0511":["Начните с пола, лежа на спине, поставив ноги на мяч.","Расположите мяч так, чтобы, когда ваши ноги будут вытянуты, лодыжки находились над мячом. Это будет ваше исходное положение.","Поднимите бедра от пола, перенося вес тела на лопатки и ступни.","Согните ноги в коленях, подтягивая мяч как можно ближе к себе, напрягая подколенные сухожилия.","После короткой паузы вернитесь в исходное положение."],"fe_ee435c8e":["Используя ленту длиной 41 дюйм, встаньте на один конец, слегка расставив ноги. Согнитесь в бедрах, чтобы завязать конец ленты петлей у себя за шеей. Это будет ваше исходное положение.","Держа ноги прямыми, вытяните их в бедрах, чтобы они приняли почти вертикальное положение.","Убедитесь, что вы не сгибаете спину, когда возвращаетесь в исходное положение."],"fe_e7aaa024":["Оберните ленту вокруг столба. Отойдя немного в сторону, оберните противоположный конец вокруг шеи. Ваши руки могут помочь закрепить ленту на месте.","Начните с прогибания в бедрах, отводя ягодицы назад как можно дальше. Держите спину ровно и наклонитесь вперед примерно на 90 градусов. Колени должны быть лишь слегка согнуты.","Вернитесь в исходное положение, двигая бедрами, чтобы вернуться в положение стоя."],"fe_221f9f3f":["Закрепите ленту вокруг прочного столба или другого объекта.","Встаньте левым боком к стойке и просуньте правую ногу в ленту, обхватив ее вокруг лодыжки.","Встаньте прямо и, при необходимости, держитесь за стойку. Это будет ваше исходное положение.","Держа колено прямым, разведите правые ноги в стороны как можно дальше.","Вернитесь в исходное положение и повторите упражнение с желаемым количеством повторений.","Смените сторону."],"fe_c5980115":["Начните с того, что вытяните руки прямо перед собой, держа ленту обеими руками.","Начните движение с выполнения обратного махового движения, разводя руки в стороны.","При выполнении движения держите локти вытянутыми, прижимая бандаж к груди. Следите за тем, чтобы во время выполнения упражнения плечи были отведены назад.","Завершив движение, сделайте паузу и вернитесь в исходное положение под контролем."],"fe_b768feb9":["Закрепите ленту у основания стойки или на скамье. Лягте на скамью так, чтобы лента была на уровне вашей головы.","Возьмитесь за бандаж, поднимая локти так, чтобы предплечье было перпендикулярно полу. При согнутом локте бандаж должен находиться у вас над головой. Это будет ваше исходное положение.","Вытяните руку в локте, чтобы выпрямить ее, удерживая предплечье на месте. В конце движения сделайте паузу и вернитесь в исходное положение."],"fe_2253e51d":["Для выполнения этого упражнения вам нужно будет встать в положение отжимания, но вместо того, чтобы отталкиваться руками от пола, вы будете хвататься за олимпийскую штангу (по 5-10 фунтов с каждой стороны). Это будет ваше исходное положение.","Слегка выгибая спину, поднимите бедра и на выдохе подтяните штангу к стопам. Совет: При выполнении упражнения ваши ягодичные мышцы должны подниматься вверх, пресс должен быть напряжен, а спина должна постоянно оставаться в вертикальном положении. Также ваши руки должны оставаться перпендикулярными полу на протяжении всего движения. Если вы этого не сделаете, то плечи и спина будут работать больше, чем пресс.","После второго сокращения в верхней точке начинайте на вдохе медленно опускать штангу обратно вперед в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_1b6b374d":["Лягте на наклонную скамью, руки, держащие штангу, должны быть опущены горизонтально. Это будет ваше исходное положение.","Удерживая предплечья неподвижными, поднимите вес тела как можно выше, одновременно сжимая бицепсы. При выполнении этой части упражнения делайте выдох. Совет: Двигать следует только предплечьями. Не размахивайте руками.","После второго сокращения на вдохе медленно вернитесь в исходное положение. Совет: Убедитесь, что вы опускаетесь до конца.","Повторите рекомендуемое количество повторений."],"fe_c3cd5826":["Начните с того, что сядьте на пол, поставив скамью прямо позади себя. Положите нагруженную штангу на ноги. Использование толстой штанги или подкладки на турник может значительно уменьшить дискомфорт, вызываемый этим упражнением.","Поднимите штангу так, чтобы она находилась прямо над вашими бедрами, и откиньтесь назад на скамью так, чтобы ваши лопатки были почти на уровне ее верхней части.","Начните движение с движения ступнями, вытягивая бедра вертикально через перекладину. Ваш вес должен поддерживаться лопатками и ступнями. Вытянитесь как можно дальше, затем выполните обратное движение, чтобы вернуться в исходное положение."],"fe_55548916":["Положите нагруженную штангу на пол рядом с концом скамьи. Встаньте на колени, поставив обе ноги на скамью, и возьмитесь за штангу средним или узким хватом. Это будет ваше исходное положение.","Для начала разгибайтесь в бедрах, чтобы медленно перекатывать штангу вперед. Во время переката сгибайте плечи, чтобы поднимать штангу над головой. Следите за тем, чтобы ваши руки оставались вытянутыми на протяжении всего движения.","Когда штанга будет выдвинута как можно дальше вперед, вернитесь в исходное положение."],"fe_ad80b92c":["Встаньте прямо, ноги на ширине плеч, и держите штангу обеими руками за спиной вытянутым хватом (ладони обращены назад). Совет: Ваши руки должны быть немного шире, чем на ширине плеч. Для лучшего захвата в этом упражнении вы можете использовать обхваты запястий. Это будет ваша исходная позиция.","На выдохе поднимите плечи как можно выше и задержите их на секунду. Совет: Воздержитесь от попыток поднять штангу, используя бицепсы. Руки все время должны оставаться вытянутыми в стороны.","На вдохе медленно вернитесь в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_7129ad50":["Встаньте прямо, держа штангу на задней поверхности плеч (немного ниже шеи). Ноги должны быть на ширине плеч. Это будет ваше исходное положение.","Держа спину прямой и глядя вперёд, наклоняйтесь только в пояснице вправо, насколько возможно. Вдыхайте при наклоне. Задержитесь на секунду и вернитесь в исходное положение на выдохе. Совет: остальное тело должно оставаться неподвижным.","Теперь повторите движение с наклоном влево. Задержитесь на секунду и вернитесь в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_bdf36d05":["Начните стоять, расставив ноги на ширину плеч и положив штангу на верхнюю часть спины.","Сделайте шаг вперёд одной ногой и сгибайте колени, опуская таз. Опускайтесь, пока колено задней ноги почти не коснётся пола. Корпус держите вертикально, переднее колено — над стопой.","Оттолкнитесь пяткой передней ноги и разогните оба колена, поднимаясь вверх.","Шагните вперёд задней ногой, выполняя выпад на другую сторону."],"fe_9d024c46":["Надев упряжь или свободный пояс с весом, прикрепите цепь сзади так, чтобы вы стояли лицом от саней. Наклонитесь, опустив руки на пол. Спина прямая, колени согнуты. Это исходное положение.","Начните движение ногами, чередуя левую и правую. Руками сохраняйте равновесие и помогайте тянуть. Старайтесь держать спину прямой на заданной дистанции."],"fe_f7389a76":["Начните с ящика или скамьи в 1-2 футах перед собой. Встаньте так, чтобы ноги были на ширине плеч. Это будет ваше исходное положение.","При подготовке к прыжку выполните короткое приседание; заведите руки за спину.","Оттолкнитесь от этого положения, разгибаясь в тазобедренных суставах, коленях и голеностопах, и выпрыгните как можно выше. Вынесите руки вперёд и вверх.","Перепрыгните через скамью, приземляйтесь с согнутыми коленями, поглощая удар ногами.","Повернитесь лицом в противоположную сторону, затем перепрыгните обратно через скамейку."],"fe_a0de7c59":["Встаньте на землю, поставив одну ногу на скамью или ящик так, чтобы пятка была близко к краю.","Оттолкнитесь ногой от верхней части скамьи, вытягивая ее через бедро и колено.","Приземляйтесь противоположной ногой на верхнюю часть ящика, возвращая другую ногу в исходное положение.","Продолжайте переминаться с ноги на ногу, чтобы завершить упражнение."],"fe_6a512480":["Встаньте прямо, держа по гантели в каждой руке и поставив перед собой наклонную скамью.","Держа спину прямо и сохраняя естественный изгиб, наклонитесь вперед, пока ваш лоб не коснется скамьи перед вами. Руки должны висеть перед вами перпендикулярно полу. Ладони ваших рук должны быть обращены друг к другу, а туловище — параллельно полу. Это будет ваша исходная позиция.","Держа туловище вытянутым вперед и неподвижным, а руки прямыми, слегка согнутыми в локтях, поднимайте гантели прямо в стороны, пока обе руки не окажутся параллельны полу. Поднимая гантели, делайте выдох. Внимание: избегайте раскачивания туловища или отведения рук назад, а не в стороны.","После секундного сокращения в верхней точке медленно опустите гантели в исходное положение.","Повторите рекомендуемое количество раз."],"fe_65fca891":["Выберите вес и возьмитесь правой рукой за ручку нижнего шкива.","Прогнитесь в талии так, чтобы ваш торс был почти параллелен полу. Ноги должны быть слегка согнуты, а левая рука должна лежать на нижней части левого бедра. Правая рука должна свисать с плеча перед вами и слегка согнута в локте. Это будет ваша исходная позиция.","Поднимите правую руку, слегка согнутую в локте, в сторону, пока она не окажется параллельно полу и на одной линии с вашим правым ухом. При выполнении этого шага сделайте выдох.","На вдохе медленно опустите вес тела обратно в исходное положение.","Повторите рекомендуемое количество раз и повторите движение другой рукой."],"fe_9d0cada2":["Навесьте вес на один конец олимпийского грифа. Другой конец уприте в угол двух стен или придавите тяжёлым предметом, чтобы гриф не сдвигался назад.","Наклонитесь вперёд, насколько возможно приближая корпус к параллели с полом, колени слегка согнуты.","Теперь возьмитесь за штангу обеими руками сразу за пластинами с той стороны, где был размещен вес, а другую руку положите на колено. Это будет ваше исходное положение.","Поднимите штангу прямо вверх, согнув локти (для максимальной стимуляции спины), пока пластины не коснутся нижней части груди. Напрягите мышцы спины, поднимая вес, и задержитесь на секунду в верхней части упражнения. Выдохните, поднимая вес. Совет: Используйте тросовое крепление с помощью стремени или двойной ручки, продев его под конец штанги.","Медленно опустите штангу в исходное положение, хорошо растягивая широчайшие. Совет: не давайте дискам касаться пола. Для максимальной амплитуды рекомендую небольшие диски (25 фунтов) вместо крупных (35–45 фунтов).","Повторите рекомендуемое количество повторений."],"fe_02571964":["Для начала сядьте на велотренажёр и отрегулируйте седло под свой рост."],"fe_56ee0dd4":["Начните с того, что лягте на скамью и, по возможности, поднимите голову над перекладиной. От одной до пяти досок, сделанных из брусков 2х6, можно скрутить вместе и удерживать на месте с помощью партнера по тренировкам, бандажей или просто засунуть под рубашку.","Подтяните ноги под себя и выгните спину дугой. Опираясь на штангу, чтобы удерживать вес тела, оторвите плечи от скамьи и отведите их назад, сведя лопатки вместе. Упритесь ступнями в скамью. Сохраняйте это напряженное положение тела на протяжении всего движения.","Вы можете взять штангу стандартным хватом или на ширине плеч, чтобы сосредоточить внимание на трицепсах. Вытяните штангу из стойки, не разгибая плечи. Штанга, запястье и локоть должны всегда находиться на одной линии. Сосредоточьтесь на том, чтобы сжимать штангу и пытаться ее раздвинуть.","Опустите штангу на доски, а затем поднимите ее вверх с максимально возможной силой. Локти должны быть согнуты до упора."],"fe_309f232f":["Положите на землю рядом друг с другом две штанги EZ с одинаковой нагрузкой. Убедитесь, что они могут катиться.","Примите положение отжимания от брусьев, перенося вес тела на носки и кисти, вытянув руки и выпрямив туловище.","Положите руки на брусья. Это будет ваше исходное положение.","Медленными и контролируемыми движениями отведите руки от средней линии тела, разводя брусья в стороны. Во время этой части движения сделайте вдох.","Раздвинув штанги как можно дальше друг от друга, вернитесь в исходное положение, снова сведя их вместе. Выполняя это движение, выдохните."],"fe_73f61259":["Встаньте, ноги на ширине плеч. Вы можете заложить руки за голову. Это будет ваше исходное положение.","Начните движение, сгибая колени и тазобедренные суставы и отводя таз назад.","Продолжайте опускаться на полную глубину, если сможете, и быстро повторяйте движение в обратном направлении, пока не вернетесь в исходное положение. Когда вы приседаете, поднимите голову и грудь и раздвиньте колени."],"fe_cefcfc24":["Примите расслабленную позу лицом к боксу или помосту примерно на расстоянии вытянутой руки. Руки должны быть опущены по бокам, а ноги слегка согнуты.","Используя руки для помощи в начальном рывке, прыгайте вверх и вперед, одновременно приземляясь ногами на ящик или платформу.","Немедленно опуститесь или прыгните обратно на исходное место; затем повторите последовательность действий."],"fe_03380345":["Вам понадобится несколько коробок, расставленных в ряд примерно на расстоянии 8 футов друг от друга.","Встаньте лицом к первому ящику, поставив одну ногу немного позади другой.","Отведите заднюю ногу в сторону, стараясь поднять бедра как можно выше.","Сразу после приземления на ящик, выбросьте другую ногу вперед и вверх, чтобы набрать высоту и дистанцию, прыгая с ящика. Приземляйтесь между первыми двумя ящиками той же ногой, которой приземлились на первый ящик.","Затем перейдите к следующему блоку и повторите то же самое."],"fe_39d29d43":["Бокс-присед позволяет вам приседать на нужную глубину и развивать взрывную силу при выполнении приседаний. Начните с силовой стойки, поставив бокс на соответствующей высоте позади себя. Как правило, вы стремитесь к такой высоте бокса, которая позволяет вам выполнять параллельные приседания, но при желании вы можете тренироваться выше или ниже.","Начните с того, что встаньте под перекладину и положите ее на заднюю поверхность плеч. Сведите лопатки вместе и выдвиньте локти вперед, пытаясь согнуть штангу, перекинув ее через плечи. Снимите штангу со стойки, создавая плотную дугу в пояснице, и вернитесь в исходное положение. Расставьте ноги шире, чтобы усилить нагрузку на спину, ягодичные мышцы, приводящие мышцы бедра и подколенные сухожилия, или ближе друг к другу, чтобы лучше проработать квадрицепсы. Держите голову прямо.","Держа спину, плечи и корпус в напряжении, отводите колени и таз назад, начиная опускаться. Отводите таз назад, пока не сядете на ящик. В идеале голени должны быть перпендикулярны полу. Остановитесь на ящике и расслабьте сгибатели бедра. Никогда не отталкивайтесь от ящика рывком.","Держа вес на пятках и отводя стопы и колени в стороны, отталкивайтесь от ящика вверх, ведя движение головой. Продолжайте, сохраняя напряжение от головы до пят."],"fe_93f021f2":["Лягте на бок, положив предплечье на поролоновый валик. Предплечье должно быть более или менее на одной линии с телом, а внешняя сторона бицепса должна быть прижата к поролоновому валику.","Поднимите бедра от пола, перенося вес тела на руки и ступни. Задержитесь на 10-30 секунд, а затем поменяйтесь сторонами."],"fe_c1d3b963":["Поднимите блоки в верхнее положение, выберите сопротивление и возьмите по рукояти в каждую руку.","Встаньте прямо между двумя блоками, разведя руки в стороны. Голова и грудь должны быть приподняты, а руки должны образовывать букву «Т». Это будет ваше исходное положение.","Держа локти вытянутыми, вытяните руки прямо в стороны.","Верните руки в исходное положение после паузы на пике сокращения.","Продолжайте движение в течение предписанного количества повторений."],"fe_fba8bec9":["Встаньте на тренажер для голеней так, чтобы подплечники находились над вашими плечами. Туловище должно быть прямым, руки должны быть вытянуты вдоль тела. Это будет ваше исходное положение.","На выдохе поднимите плечи к ушам и задержите сжатие на целую секунду.","На вдохе медленно вернитесь в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_c52fc16d":["Возьмите тренажерную ленту и встаньте на нее пальцами ног, следя за тем, чтобы длина ленты между стопой и руками была одинаковой с обеих сторон.","Держась за ручки бандажа, поднимите руки в стороны от головы, как будто вы готовитесь выполнять жим плечами. Ладони должны быть направлены вперед, а локти согнуты в стороны. Это движение создаст натяжение бандажа. Это будет ваша исходная позиция.","Держа руки на уровне плеч, на выдохе поднимитесь на носочки и сильно напрягите икры в начале движения.","После секундного сокращения медленно вернитесь в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_979b52dd":["Начните с положения сидя на полу. Подложите под голень поролоновый валик. Вторую ногу можно либо перекинуть через противоположную, либо поставить на пол, поддерживая часть своего веса. Это будет ваше исходное положение.","Расположите руки по бокам или чуть позади себя и надавите на них, чтобы оторвать бедра от пола, перенося большую часть своего веса на икроножные мышцы. Перекатывайтесь от уровня ниже колена к уровню выше лодыжки, задерживаясь в точках напряжения на 10-30 секунд. Повторите то же самое для другой ноги."],"fe_38e0ed51":["У такой соревновательной конструкции обычно нейтральные рукояти, но встречаются и прямые грифы — с ними подход как в обычной становой. Конструкцию нагружают автомобилем или другими тяжёлыми предметами, например покрышками трактора или бочками.","Встаньте по центру между рукоятями, если сильны в приседе, или чуть сзади, если сильны в становой. Стопы примерно на ширине таза. Наклонитесь в тазобедренных суставах и возьмитесь за рукояти. Когда стопы и хват установлены, сделайте глубокий вдох, опустите таз и согните колени.","Смотрите вперёд, грудь поднята, спина прогнута — начинайте тянуть вес вверх, отталкиваясь пятками. Когда вес идёт вверх, сводите лопатки, подавая таз вперёд.","Опустите вес, наклоняясь в тазобедренных суставах и направляя его к полу."],"fe_7617a80b":["Стоя прямо, держите штангу обеими руками в положениях «3» и «9 часов». Ваши ладони должны быть обращены друг к другу, а руки вытянуты прямо перед собой. Это будет ваше исходное положение.","Начните движение, повернув пластину как можно дальше в одну сторону. Используйте те же движения, которые вы использовали бы для поворота рулевого колеса в одну сторону.","Повторите движение в обратном направлении, полностью поворачивая его в противоположную сторону.","Повторите рекомендуемое количество повторений."],"fe_0e398d77":["Начните с того, что расставьте ноги на несколько дюймов друг от друга и поднимите левую руку вверх в расслабленном, спортивном положении.","Правой ногой быстро сделайте шаг назад и подтяните колено вверх.","Вытягивая правое колено, поднимайте руки назад, следя за тем, чтобы колено двигалось вертикально вверх и вниз. Старайтесь не поворачивать ступни при движении и продолжайте смотреть вперед, двигаясь в сторону."],"fe_efa54bbb":["Встаньте на пол на четвереньки.","Втяните живот и округлите позвоночник, поясницу, плечи и шею, опустив голову.","Задержитесь на 15 секунд."],"fe_389668ed":["Для этого упражнения вам понадобятся две тросовые ручки и плоская скамья, а также цепи. Прикрепите середину цепей к ручкам и встаньте на плоскую скамью. Ваши локти должны быть направлены прямо вверх.","Начните с разгибания в локте, удерживая предплечье неподвижным, а запястья вытянутыми вперед.","Сделайте паузу в момент блокировки и повторите движение в обратном направлении, чтобы вернуться в исходное положение."],"fe_4701f750":["Начните с подсоединения цепей к тросовым рукояткам. Расположитесь на плоской скамье в том же положении, что и для жима гантелей. Ваши запястья должны быть вытянуты вперед, а руки перпендикулярны полу. Это будет ваше исходное положение.","Опустите цепи, согнув руки в локтях, чтобы часть цепи упала на пол.","Продолжайте, пока ваш локоть не образует угол в 90 градусов, а затем повторите движение в обратном направлении, разгибая локоть до упора."],"fe_d6a43a86":["Сядьте на краешек стула, держась за его спинку.","Выпрямите руки, держа спину прямо, и вытяните верхнюю часть туловища вперед, чтобы почувствовать растяжение. Задержитесь на 20-30 секунд."],"fe_980f74fc":["Встаньте на четвереньки, вытяните руки перед собой.","Опустите ягодицы вниз, чтобы сесть на пятки. Когда вы откидываетесь назад, пусть ваши руки будут волочиться по полу, чтобы растянуть весь позвоночник.","Как только вы опуститесь на пятки, положите руки рядом со ступнями и расслабьтесь. «дышите» в спину. Упритесь лбом в пол. Избегайте этой позы, если у вас проблемы с коленями."],"fe_afede2f4":["Примите сидячее положение на полу.","Положите обе руки на затылок, сцепив пальцы, большие пальцы направлены вниз, а локти направлены прямо вперед. Медленно опустите голову на грудь. Задержитесь на 20-30 секунд."],"fe_d7839951":["Цирковой колокол — огромная гантель с толстой рукоятью. Начните с гантелью между стопами и возьмитесь за рукоять обеими руками.","Забросьте гантель, разгибаясь в тазобедренных суставах и коленях, подавая снаряд к нужному плечу и отпуская лишнюю руку.","Убедитесь, что один шар гантели оказался за плечом — так вас не собьёт с равновесия. Чтобы поднять её над головой, присядьте, сгибая колени, и вытолкните гантель вверх, слегка отклоняясь в противоположную сторону.","Аккуратно направьте колокол обратно на пол, удерживая контроль. Лучше выполнять это упражнение на толстом резиновом коврике, чтобы не повредить пол."],"fe_a708b446":["Поставив штангу на пол рядом с голенями, возьмитесь за штангу хватом сверху вниз (или крюком), расположенным снаружи ног. Опустите бедра, сосредоточив вес на пятках, спина прямая, голова направлена вперед, грудь приподнята, плечи находятся прямо перед перекладиной. Это будет ваша исходная позиция.","Undefined.","Начните первый подъём, отталкиваясь пятками и разгибая колени. Угол наклона спины должен сохраняться, руки — оставаться прямыми. Поднимайте вес подконтрольно, пока гриф не пройдёт колени.","Далее следует второй подъём — главный источник ускорения во взятии. Когда гриф приближается к середине бедра, начинайте разгибаться в тазобедренных суставах. Прыжковым движением ускоряйте штангу вверх, разгибая тазобедренные суставы, колени и голеностопы. Активно тянуть руками не нужно: в конце второго подъёма тело полностью выпрямлено и слегка отклонено назад, руки всё ещё прямые.","Достигнув полного разгибания, переходите к третьему подъёму: энергично выполните шраг и согните руки, поднимая локти вверх и в стороны. В точке пикового разгибания резко уводите себя под гриф, разворачивая локти под него. Примите штангу в положении фронтального приседа — глубина зависит от высоты грифа в конце третьего подъёма. Штанга ложится на выведенные вперёд плечи, слегка касаясь горла, кисти расслаблены. Продолжайте опускаться в глубокий присед — это поможет вставанию.","Сразу же вставайте, отталкиваясь пятками, держа корпус вертикально и локти поднятыми. Продолжайте, пока не встанете в полный рост."],"fe_c84620de":["Начните стоять, держа штангу близко к голеням. Ваши ступни должны быть прямо под бедрами, ступни слегка развернуты. Возьмитесь за перекладину двойным хватом сверху вниз или хватом крюком, примерно на ширине плеч. Присядьте на корточки перед перекладиной. Ваш позвоночник должен быть полностью выпрямлен, при этом угол наклона спины должен быть таким, чтобы плечи находились перед перекладиной, а спина была максимально вертикальной.","Начните с того, что отталкивайтесь от пола пятками. По мере того, как штанга поднимается вверх, сохраняйте постоянный угол наклона спины. Разведите колени в стороны, чтобы они не попадали на штангу.","После того как штанга пересечет колени, завершите подъем, вдавливая бедра в штангу до тех пор, пока ваши бедра и колени не будут выпрямлены."],"fe_30711b62":["Со штангой на полу у голеней возьмитесь прямым хватом или «замком» чуть шире ног. Опустите таз, вес на пятках, спина прямая, взгляд вперёд, грудь поднята, плечи чуть впереди грифа. Это исходное положение.","Начните первую тягу с движения пятками, разгибая колени. Угол наклона спины должен оставаться прежним, руки должны оставаться прямыми, локти должны быть разведены в стороны. Контролируйте вес, продолжая поднимать его выше колен.","Затем следует второй рывок, который является основным источником ускорения для выполнения толчка. Когда штанга приблизится к середине бедра, начинайте разгибать бедра. При выполнении прыжкового движения ускоряйтесь, разгибая бедра, колени и лодыжки, используя скорость для перемещения штанги вверх. Не должно быть необходимости активно вытягивать руки, чтобы увеличить вес; в конце второго рывка тело должно быть полностью выпрямлено, слегка отклоняясь назад, при этом руки все еще должны быть вытянуты. Полное удлинение должно быть сильным и резким, и следите за тем, чтобы вы не продлевали удлинение дольше, чем это необходимо."],"fe_6c25c740":["Начните с хвата на ширине плеч (прямой или «замок»), гриф висит на уровне середины бедра. Спина прямая и слегка наклонена вперёд.","Поднимите плечи к ушам. Хотя в этом упражнении обычно используется больший вес, чем в чистом, избегайте перегрузки до такой степени, что выполнение замедлится."],"fe_cd806e69":["Со штангой на полу у голеней возьмитесь прямым хватом или «замком» чуть шире ног. Опустите таз, вес на пятках, спина прямая, взгляд вперёд, грудь поднята, плечи чуть впереди грифа. Это исходное положение.","Начните первый подъём, отталкиваясь пятками и разгибая колени. Угол наклона спины должен сохраняться, руки — оставаться прямыми. Поднимайте вес подконтрольно, пока гриф не пройдёт колени.","Далее следует второй подъём — главный источник ускорения во взятии. Когда гриф приближается к середине бедра, начинайте разгибаться в тазобедренных суставах. Прыжковым движением ускоряйте штангу вверх, разгибая тазобедренные суставы, колени и голеностопы. Активно тянуть руками не нужно: в конце второго подъёма тело полностью выпрямлено и слегка отклонено назад, руки всё ещё прямые.","Достигнув полного разгибания, переходите к третьему подъёму: энергично выполните шраг и согните руки, поднимая локти вверх и в стороны. В точке пикового разгибания резко уводите себя под гриф, разворачивая локти под него. Примите штангу в положении фронтального приседа — глубина зависит от высоты грифа в конце третьего подъёма. Штанга ложится на выведенные вперёд плечи, слегка касаясь горла, кисти расслаблены. Продолжайте опускаться в глубокий присед — это поможет вставанию.","Сразу же вставайте, отталкиваясь пятками, держа корпус вертикально и локти поднятыми. Продолжайте, пока не встанете в полный рост.","Вторая фаза — это рывок, при котором вес тела поднимается над головой. Стоя с отягощением на передней поверхности плеч, начните с наклонов. Расположив ступни прямо под бедрами, согните колени, не отводя бедра назад. Опускайтесь совсем немного и меняйте направление движения как можно сильнее.","Отталкиваясь пятками, создайте максимальную скорость и силу и обязательно уберите голову с траектории, когда штанга покидает плечи.","В тот момент, когда ступни отрываются от пола, их необходимо как можно быстрее поставить в исходное положение. В тот короткий момент, когда ступни не будут активно упираться в платформу, усилие спортсмена, направленное на поднятие штанги, приведет к их опусканию. Ноги должны быть разведены в стороны, одна нога должна быть выдвинута вперед, а другая — назад. Примите штангу, вытянув руки над головой. Вернитесь в положение стоя."],"fe_d36894f8":["Расположив штангу на ящиках или стойках нужной высоты, возьмитесь за нее сверху или крючком, расположенным чуть выше ног. Опустите бедра, сосредоточив вес на пятках, спина прямая, голова направлена вперед, грудь приподнята, плечи находятся прямо перед перекладиной. Это будет ваша исходная позиция.","Начните первую тягу с движения пятками, разгибая колени. Угол наклона спины должен оставаться прежним, а руки — прямыми, локти должны быть направлены вперед.","Когда вы достигнете полного разгибания, переходите в исходное положение, энергично пожимая плечами и сгибая руки в локтях вверх и в стороны. Энергично опускайтесь вниз, вращая локтями под перекладиной. Примите штангу в положении переднего приседа, глубина которого зависит от высоты штанги в конце третьего рывка. Штангу следует положить на вытянутые плечи, слегка касаясь горла расслабленными руками. Продолжайте опускаться в нижнее положение на корточках, которое поможет в восстановлении сил.","Немедленно вернитесь в исходное положение, работая пятками, держа туловище вертикально, а локти поднятыми. Продолжайте, пока не встанете в положение стоя. Для следующего повторения верните вес на боксы."],"fe_0d33a637":["С нагруженным весом возьмите конец снаряда хватом Зерчера. Гриф в сгибе локтя, кисти держитесь за запястье. Старайтесь не нагружать предплечья.","Начните поднимать вес с пола. Держите жёсткую вертикальную осанку, начиная идти короткими быстрыми шагами. Смотрите вверх и в сторону, когда идёте по кругу. Не задерживайте дыхание. Идите, пока не завершите один или более полных кругов."],"fe_63a03475":["Закрепите тренажерную ленту вокруг неподвижной стойки.","Отвернувшись от стойки, возьмитесь за ручки на обоих концах ленты и сделайте достаточный шаг вперед, чтобы создать натяжение ленты.","Разведите руки в стороны параллельно полу, перпендикулярно туловищу (туловище и руки должны напоминать букву «Т»), ладонями вперед. Вытяните их, слегка согнув в локтях. Это будет ваше исходное положение.","Держа руки прямыми, на выдохе разведите их полукруглыми движениями вдоль груди вперед и напрягите грудные мышцы. Задержите сжатие на секунду.","На вдохе медленно вернитесь в исходное положение.","Выполняйте рекомендованное количество повторений."],"fe_8146683f":["Встаньте, поставив стопы на ширине плеч. Это исходное положение.","Выполните выпад назад, отступив назад одной ногой и согнув бедра и переднее колено. При этом поверните туловище поперек передней ноги.","После короткой паузы вернитесь в исходное положение и повторите упражнение с другой стороны, продолжая чередовать движения."],"fe_9eaee395":["В «распятии» вы статически удерживаете вес в стороны на время. Хотя можно тренироваться с гантелями, лучше практиковать с теми снарядами, что используются на соревнованиях — топорами и молотами, — они ощущаются иначе.","Начните стоя и поднимите руки в стороны, удерживая снаряды. Руки параллельны полу. На соревнованиях судьи или датчики сигнализируют, когда вы опустили руки ниже параллели. Удерживайте как можно дольше. Обычно вес должен быть таким, чтобы вы закончили за 30–60 секунд."],"fe_afeccc9e":["Лягте на спину, поставив ноги на гимнастический мяч и согнув колени под углом 90 градусов.","Расставьте ступни на расстоянии трех-четырех дюймов друг от друга и направьте пальцы ног внутрь, чтобы они соприкасались.","Слегка расположите руки по обе стороны от головы, согнув локти. Совет: Не сцепляйте пальцы за головой.","Прижмите поясницу к полу, чтобы лучше изолировать мышцы живота. Это будет ваше исходное положение.","Начните отрывать плечи от пола и продолжайте изо всех сил давить на нижнюю часть спины. Ваши плечи должны отрываться от пола всего на четыре дюйма, а нижняя часть спины должна оставаться на полу. При выполнении этой части движения сделайте выдох. Сильно напрягите мышцы брюшного пресса в верхней точке сокращения и задержитесь на секунду. Совет: Сосредоточьтесь на медленном, контролируемом движении. Ни в коем случае не используйте инерцию.","На вдохе медленно вернитесь в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_27f52397":["Сядьте прямо на пол.","Положите правую ногу на левую, согнув ее в колене. Левая нога прямая и опущена на пол.","Положите левую руку на правую ногу, а правую — на пол.","Поверните верхнюю часть туловища вправо и задержитесь в таком положении на 10-20 секунд. Поменяйтесь сторонами."],"fe_d44f1dbe":["Вы можете прикрепить цепи к рукавам штанги или просто накинуть их посередине на штангу, чтобы увеличить вес при подъеме.","Подойдите к перекладине так, чтобы она находилась по центру ваших ступней. Ваши ступни должны быть примерно на ширине бедер. Согнитесь в бедрах, чтобы обхватить перекладину на ширине плеч, позволяя лопаткам вытянуться. Как правило, в более тяжелых подходах вы используете хват сверху или снизу. Расставив ноги и зафиксировав хват, сделайте глубокий вдох, а затем опустите бедра и согните колени, пока голени не коснутся перекладины.","Наклоните голову вперед, поднимите грудь и выгните спину дугой и начинайте давить на пятки, чтобы переместить вес тела вверх. После того, как штанга пройдет над коленями, энергично отведите штангу назад, сведя лопатки вместе, когда вы будете толкать бедра вперед, к штанге.","Опустите штангу, наклоняясь в тазобедренных суставах и направляя её к полу."],"fe_7654a3c6":["Зафиксируйте ноги в конце скамьи с отрицательным наклоном и медленно лягте на неё.","Используя сжатый хват (хват, который немного меньше ширины плеч), поднимите штангу из стойки и держите ее прямо над собой, сцепив руки в замок и согнув локти. Руки должны быть перпендикулярны полу. Это будет ваше исходное положение. Совет: Чтобы защитить вашу вращательную манжету плеча, лучше всего, если вам будет помогать корректировщик поднимать штангу со стойки.","Теперь на вдохе опустите штангу к низу груди. Держите локти прижатыми во время движения.","Используя трицепсы, чтобы поднять штангу обратно вверх, на выдохе верните ее в исходное положение.","На вдохе, удерживая плечи неподвижными, медленно опустите гриф, описывая предплечьями полукруг к себе, пока он слегка не коснётся лба. Вдыхайте во время этой фазы движения.","Верните гриф в исходное положение, сокращая трицепсы, на выдохе.","Повторяйте шаги 3-6 до тех пор, пока не будет выполнено рекомендуемое количество повторений."],"fe_19bacbfe":["Для начала подготовьте платформу или утяжелители, на которые вы можете встать, обычно высотой 1-3 дюйма. Поставьте штангу так, чтобы она находилась по центру ваших ступней. Ваши ступни должны быть примерно на ширине бедер. Согнитесь в бедрах, чтобы взяться за штангу на ширине плеч, позволяя лопаткам вытянуться. Как правило, в более тяжелых подходах вы используете хват сверху вниз.","Когда стопы и хват установлены, сделайте глубокий вдох, опустите таз и согните колени, пока голени не коснутся грифа. Смотрите вперёд, грудь поднята, спина прогнута — начинайте тянуть вес вверх, отталкиваясь пятками. После того как гриф пройдёт колени, энергично тяните его к себе, сводя лопатки и подавая таз вперёд к грифу.","Опустите штангу, наклоняясь в тазобедренных суставах и направляя её к полу."],"fe_854631ae":["Для этого упражнения вам понадобятся два ящика или скамейки, одна высотой от 12 до 16 дюймов, а другая — от 22 до 26 дюймов.","Встаньте на один из двух ящиков, разведя руки в стороны; ноги должны быть вместе и немного в стороне от края, как при прыжке в глубину. Поставьте другой ящик примерно в двух-трех футах перед исполнителем и лицом к нему.","Начните с того, что выпрыгните из начальной коробки, приземляйтесь и одновременно взлетайте обеими ногами.","Оттолкнитесь, двигаясь вверх и в стороны как можно интенсивнее, используя руки и полное разгибание туловища, чтобы запрыгнуть на более высокий ящик. Опять же, позвольте ногам смягчить удар."],"fe_41f00fac":["Начните стоять, слегка согнув колени.","Быстро присядьте на короткое расстояние, сгибая бедра и колени, и сразу же выпрямитесь, чтобы подпрыгнуть на максимальную вертикальную высоту.","Поднимаясь, подтяните пятки, сгибая колени, стараясь коснуться ягодиц.","Завершите движение приземлением, лишь частично согнув колени и используя ноги для амортизации удара."],"fe_ccb7b35e":["Лягте лицом вниз на гимнастический мяч.","Лежа животом на мяче, проведите руками вперед по полу и поднимите ноги, выпрямляя локти и колени."],"fe_a379dd4d":["Расположите низкие ящики или другие платформы на расстоянии 2-3 футов друг от друга.","Встаньте в положение отжимания между ними, опираясь руками о ящики.","С хорошей осанкой прыгайте с платформы, подтягиваясь и разводя руки на ширину плеч, смягчая приземление за счет поглощения удара рукой."],"fe_3a88fabe":["Лягте на пол, держа гантели в руках. Колени могут быть согнуты. Начните с того, что гантели будут полностью подняты над вами.","Опускайте гантели до тех пор, пока ваша верхняя часть руки не коснется пола. Вы можете согнуть локти, чтобы подчеркнуть размер и силу трицепсов, или, чтобы сосредоточить внимание на груди, развести руки в стороны.","Задержитесь внизу, а затем перенесите вес тела вместе в верхней точке, разгибаясь на локтях."],"fe_bcca803e":["Это корректирующее упражнение укрепляет мышцы, которые стабилизируют вашу лопатку. Держите по небольшому грузу в каждой руке, разведя их в стороны. Большие пальцы должны быть направлены вверх.","Начните движение, вытягивая руки перед собой, примерно на 30 градусов от центра. При выполнении движения ваши руки должны быть полностью вытянуты.","Продолжайте, пока ваши руки не окажутся параллельны земле, а затем вернитесь в исходное положение."],"fe_ec5e03d4":["Поставьте ящик на расстоянии пары футов от скамьи. Прижмите гантели к груди обеими руками и сядьте на скамью лицом к ящику. Это будет ваше исходное положение.","Твердо поставьте ноги на землю, наклоняясь вперед, вытягивая бедра и колени, чтобы подпрыгнуть вверх и вперед.","Приземляйтесь на ящик обеими ногами, амортизируя удар, позволяя бедрам и коленям согнуться.","Сделайте шаг назад и вернитесь в исходное положение."],"fe_c8a2e0b4":["Встаньте, поставив стопы на ширине плеч. Это исходное положение.","Держа руки прямыми, взмахните ими прямо перед собой 5-10 раз, с каждым разом увеличивая амплитуду движений, пока ваши руки не окажутся над головой."],"fe_39e41e86":["Лежа на скамье, поднимите штангу EZ сжатым хватом и удерживайте ее, согнув локти. Ваши руки должны быть перпендикулярны полу. Это будет ваше исходное положение.","Удерживая верхнюю часть рук неподвижной, опустите штангу, позволяя локтям согнуться. При выполнении этой части упражнения сделайте вдох. Сделайте паузу, как только штанга окажется прямо надо лбом.","Верните штангу в исходное положение, выпрямив локоть и сделав выдох.","Повторите."],"fe_3ffb0445":["Сядьте или встаньте, слегка расставив ноги.","Положите руки на плечи так, чтобы локти были на уровне плеч и направлены наружу.","Медленно описывайте локтями круг. В начале круга сделайте выдох, а в конце — вдох."],"fe_a105e804":["Встаньте прямо.","Положите обе руки на поясницу так, чтобы пальцы были направлены вниз, а локти разведены в стороны.","Затем осторожно отведите локти назад, стараясь соприкоснуться ими друг с другом."],"fe_68227796":["Установите штангу на стойку на уровне плеч, нагруженную соответствующим весом. Установите позади себя небольшую приподнятую платформу.","Положите штангу на верхнюю часть спины, выпрямив спину. Встаньте на приподнятую платформу обеими ногами. Это будет ваше исходное положение.","Начните с шага назад одной ногой. Опускайтесь, сгибая бедра и колени, пока колено не коснется пола.","Сделайте паузу и вытяните бедра и колени, чтобы подняться вверх, полностью возвращаясь в исходное положение, прежде чем чередовать движения."],"fe_0c159918":["Возьмите какую-нибудь платформу (это может быть платформа для аэробики или для поднятия икр) высотой около 4-6 дюймов.","Поместите его на сиденье машины для укладки тросов.","Сядьте на тренажер и поставьте ноги на переднюю платформу или перекладину, убедившись, что ваши колени слегка согнуты и не зафиксированы.","Наклонитесь, сохраняя естественный прогиб спины, и возьмитесь за V-рукоять.","С выпрямленными руками отводите корпус назад, пока он не окажется под углом 90 градусов к ногам. Спина слегка прогнута, грудь вперёд. Держа гриф перед собой, вы должны чувствовать растяжение широчайших. Это исходное положение.","Держа корпус неподвижным, тяните рукояти к животу, прижимая руки к телу. Выдыхайте во время движения. В конечной точке сильно напрягите мышцы спины, задержитесь на секунду и медленно вернитесь в исходное положение на вдохе.","Повторите рекомендуемое количество повторений."],"fe_593cfa37":["Лягте на бок на горизонтальную скамью: одной рукой держите гантель, другую положите на скамью и опирайтесь на неё головой.","Согните в локте руки, держащие гантель, так, чтобы между плечом и предплечьем образовался угол в 90 градусов. Совет: Держите руки параллельно туловищу.","Теперь согните руку в локте, сохраняя при этом верхнюю часть руки неподвижной. Таким образом, предплечье будет параллельно полу и перпендикулярно вашему туловищу (совет: предплечье будет находиться прямо перед вами). Верхняя часть руки должна быть неподвижно прижата к туловищу и параллельна полу (всегда на одной линии с туловищем). Это будет ваше исходное положение.","На выдохе выполните наружную ротацию предплечья, поднимая гантель полукруглым движением и сохраняя угол 90 градусов между плечом и предплечьем. Продолжайте ротацию, пока предплечье не окажется перпендикулярно полу и корпусу, направленным в потолок. Задержитесь в этом положении на секунду.","На вдохе медленно вернитесь в исходное положение.","Повторите рекомендуемое количество повторений, затем смените руку."],"fe_cbe20356":["Обмотайте ленту вокруг столба. Лента должна быть на высоте вашего локтя. Встаньте левым боком к ленте на расстоянии пары футов.","Возьмитесь за конец ленты правой рукой, плотно прижав локоть к боку. Рекомендуем подложить под локоть валик, чтобы зафиксировать его положение.","Плечо зафиксировано, локоть согнут на 90 градусов, кисть перед корпусом. Это исходное положение.","Выполните движение, вращая рукой как при ударе тыльной стороной кисти, не сдвигая локоть.","Продолжайте, насколько возможно, задержитесь и вернитесь в исходное положение."],"fe_733d0bef":["Стоя лицом к высокому блоку с прикрепленной веревкой или двумя ручками, подтяните вес прямо к лицу, при этом разведите руки в стороны. Держите предплечья параллельно земле."],"fe_ada8ee71":["Начните в расслабленном положении, слегка выставив одну ногу вперед. Это будет ваше исходное положение.","Переходите, выполняя пошаговый переход от шага вправо-вправо к шагу влево-влево и так далее, чередуя движения вперед и назад.","Выполняйте быстрые прыжки, поддерживая тесный контакт с землей, и сокращайте время полета, двигаясь как можно быстрее."],"fe_81eff975":["Отрегулируйте j-образные крючки так, чтобы они находились на нужной высоте для установки штанги. Лягте на пол так, чтобы голова была ближе к краю силовой стойки. Сведите лопатки вместе и снимите штангу с крючков.","Опускайте гриф к низу груди или верхней части живота, сжимая гриф и как бы растягивая его в стороны. Прижимайте локти к корпусу на протяжении всего движения. Опустите, пока плечо не коснётся пола, и сделайте паузу — не допускайте удара и отскока веса.","Выжмите гриф вверх как можно быстрее, сохраняя гриф, запястья и локти на одной линии."],"fe_5424b31b":["Это упражнение растягивает фасции мышц стоп. Начните с положения сидя, сняв обувь. Используя валик для ног или аналогичный предмет, например, небольшой отрезок трубы из пвх, положите ступню на валик поперек свода стопы. Это будет ваше исходное положение.","Сильно надавите, перекатываясь по своду стопы. Задержитесь на 10-30 секунд, а затем поменяйте ногу."],"fe_e61c1367":["Прикрепите двойную рукоять (цепь или канат) к саням. Вы должны стоять лицом от саней, держа рукоять в каждой руке.","Начните движение шагом вперёд. Наклонившись вперёд, шагайте, разгибаясь в ногах и тазобедренных суставах, останавливаясь на каждом шаге, чтобы разогнуть локти и вытолкнуть руки вперёд. Шагайте вперёд, пока не вернётесь в исходную позицию, готовую к жиму."],"fe_2ff5462a":["Встаньте, заложив руки за голову, и присядьте на корточки, держа туловище прямо, а голову высоко поднятой. Это будет ваше исходное положение.","Прыгайте вперед на несколько футов, стараясь не подпрыгивать слишком высоко. Когда ваши ступни коснутся земли, амортизируйте удар ногами и прыгайте снова. Повторите это действие 5-10 раз."],"fe_8be2b06d":["Лягте спиной на пол (или коврик для упражнений), вытянув ноги перед собой.","Теперь согните ноги в коленях и прижмите внешнюю поверхность бедер к полу (или коврику) так, чтобы подошвы ваших ног касались друг друга.","Теперь попробуйте оттолкнуться обеими подошвами и подтянуть их как можно ближе к себе, при этом бедра должны находиться на внешней стороне пола (или, по крайней мере, почти касаться его). Совет: В этом положении ваши ноги должны образовывать ромбовидную форму.","Теперь скрестите руки перед собой, касаясь противоположных плеч. Это будет ваше исходное положение.","На выдохе прижмите нижнюю часть спины к полу, одновременно наклоняя туловище вверх. Совет: Это будет похоже на выполнение первой половины приседания. Задержитесь в верхнем положении на секунду.","На вдохе медленно опустите спину в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_49c960d4":["Начните с ящика соответствующей высоты на расстоянии 1-2 футов перед собой. Встаньте так, чтобы ноги были на ширине плеч. Это будет ваше исходное положение.","При подготовке к прыжку выполните короткое приседание, размахивая руками за спиной.","Оттолкнитесь от этого положения, разгибаясь в тазобедренных суставах, коленях и голеностопах, и выпрыгните как можно выше. Вынесите руки вперёд и вверх.","Приземляйтесь на ящик с согнутыми коленями, амортизируя удар ногами. Вы можете спрыгнуть с ящика обратно на землю или, предпочтительно, опускаться на него по одной ноге за раз."],"fe_4395ed1f":["Установите ряд конусов или других небольших ограждений, расположив их на расстоянии около метра друг от друга.","Встаньте перед первым конусом, ноги на ширине плеч. Это будет ваше исходное положение.","Начните с прыжка обеими ногами через первый конус, размахивая обеими руками во время прыжка.","Смягчите удар при приземлении, согнув колени, и отскочите от первого прыжка, перепрыгнув через следующий конус.","Продолжайте, пока не перепрыгнете через все конусы."],"fe_ae05bfdf":["Встаньте рядом со стулом или другой опорой, держась за нее одной рукой.","Вытяните ногу вперед, сохраняя ее прямой. Продолжайте движение вниз, отводя ногу назад настолько далеко, насколько позволяет ваша гибкость. Повторите 5-10 раз, а затем поменяйте ноги."],"fe_e1c2f111":["Встаньте на колени на пол или на коврик для упражнений и согнитесь в талии, вытянув руки перед собой (перпендикулярно туловищу), чтобы принять положение отжимания на коленях, но так, чтобы руки были на ширине плеч. Ваша голова должна быть направлена вперед, а согнутые колени должны образовывать угол в 90 градусов между подколенными сухожилиями и икрами. Это будет ваше исходное положение.","На выдохе поднимайте правую ногу до тех пор, пока подколенные сухожилия не окажутся на одной линии со спиной, сохраняя изгиб под углом 90 градусов. Во время этого движения напрягайте ягодичные мышцы и задержите их в верхней точке на секунду. Совет: В конце движения верхняя часть ноги должна быть параллельна полу, а икра — перпендикулярна ему.","На вдохе вернитесь в исходное положение и повторите упражнение левой ногой.","Продолжайте чередовать ноги до тех пор, пока не будут выполнены все рекомендуемые повторения."],"fe_a88b5363":["Начните со штанги на стойке примерно на той же высоте, что и ваш живот. Прогнитесь под перекладиной и положите ее на заднюю поверхность плеч, как при выполнении силовых приседаний, а не на верхнюю часть плеч. Стоя на нужной высоте, вы должны быть почти параллельны полу, когда наклоняетесь. Держите спину напряженной, лопатки сведены вместе, а колени слегка согнуты. Спина должна быть выгнута дугой, а шейный отдел позвоночника должен находиться в правильном положении.","Начните движение, разгибая бедра ягодицами и подколенными сухожилиями, при этом вы будете стоять с отягощением. Медленно опустите вес обратно на штифты, возвращаясь в исходное положение."],"fe_af691cf5":["Сядьте на пол, согнув колени и поставив ступни вместе.","Сцепите пальцы рук за головой. Это будет ваше исходное положение.","Прогнитесь вниз, прижав локти к внутренней стороне бедер. После небольшой паузы вернитесь в исходное положение, подняв голову и выпрямив спину. Повторите упражнение 10-20 раз."],"fe_10a7b7ec":["Начните с отжимания от пола. Это будет ваше исходное положение.","Используя обе ноги, прыгайте вперед, приземляясь так, чтобы ступни были рядом с руками. При этом держите голову высоко поднятой.","Вернитесь в исходное положение и сразу же повторите движение, продолжая в течение 10-20 повторений."],"fe_a3a2374b":["В положении сидя положите ноги на поролоновый валик так, чтобы он располагался на задней поверхности голеней. Разведите руки в стороны или за спину, чтобы поддерживать свой вес. Это будет ваше исходное положение.","Используя руки, оторвите бедра от пола и перенесите вес тела на одну ногу. Расслабьте подколенные сухожилия ноги, которую вы растягиваете.","Распределите пену от нижней части бедра до задней поверхности колена, задерживая ее в местах натяжения на 10-30 секунд. Повторите для другой ноги."],"fe_e5006c00":["Начните с хвата на ширине плеч (прямой или «замок»), гриф висит на уровне середины бедра. Спина прямая и слегка наклонена вперёд.","Начните с интенсивного вытягивания мышц за счет бедер, коленей и лодыжек, перемещая вес тела вверх. При этом двигайте плечами по направлению к ушам.","Сразу же вставайте, отталкиваясь пятками, держа корпус вертикально и локти поднятыми. Продолжайте, пока не встанете в полный рост."],"fe_8aeb1069":["Начните с положения на ширине плеч, двойным хватом или хватом крюком, при этом штанга должна находиться чуть ниже колен. Ваша спина должна быть прямой и слегка наклонена вперед.","Начните с активного вытягивания рук за счет бедер, коленей и лодыжек, перемещая вес тела вверх. При этом двигайте плечами по направлению к ушам. Когда вы достигнете полного разгибания, переходите к третьему подтягиванию, энергично пожимая плечами и сгибая руки в локтях вверх и наружу.","При максимальном разгибании резко опуститесь вниз, вращая при этом локтями под перекладиной. Примите штангу в положении переднего приседа, глубина которого зависит от высоты перекладины в конце третьего рывка. Штангу следует опустить на вытянутые плечи, слегка касаясь горла расслабленными руками. Продолжайте опускаться в нижнее положение для приседания, которое поможет в восстановлении сил.","Сразу же вставайте, отталкиваясь пятками, держа корпус вертикально и локти поднятыми. Продолжайте, пока не встанете в полный рост."],"fe_27a79037":["Начните с широкого хвата за перекладину, используя хваты сверху вниз или крюком. Ступни должны находиться прямо под бедрами, стопы должны быть развернуты. Колени должны быть слегка согнуты, а туловище наклонено вперед. Позвоночник должен быть полностью выпрямлен, а голова направлена вперед. Перекладина должна находиться на уровне бедер. Это будет ваше исходное положение.","Энергично разгибайтесь в ногах и тазобедренных суставах. В точке пикового разгибания выполните шраг плечами, позволяя локтям согнуться в стороны.","Подставляя стопы в позицию приёма, резко уводите себя под гриф, выталкивая его над голову. Примите штангу с максимально низкой посадкой, руки полностью выпрямлены над головой.","Вернитесь в положение стоя, держа вес над головой. Затем верните вес на землю под контролем."],"fe_754315f1":["Начните со штанги, установленной на стойке примерно на той же высоте, что и ваш живот. Подвесьте штангу с помощью цепей или подвесных ремней.","Прогнитесь под перекладиной и положите ее на заднюю поверхность плеч, как при выполнении силовых приседаний, а не на ягодицы. На нужной высоте, когда вы наклоняетесь, она должна быть почти параллельна полу. Держите спину напряженной, лопатки сведены вместе, колени слегка согнуты. Держите спину выгнутой, а шейный отдел позвоночника в правильном положении.","Начните движение с растягивания бедер ягодицами и подколенными сухожилиями, и вы будете стоять с отягощением.","Медленно опустите груз обратно в исходное положение, где он будет удерживаться цепями."],"fe_6fe10ba8":["Это упражнение поможет вам освоить рывок. Начните с того, что перенесите небольшой вес на заднюю поверхность плеч. Ваши ноги должны быть расставлены чуть шире, чем на ширину бедер, стопы должны быть развернуты в стороны, в том же положении, в котором вы выполняли бы приседания.","Начните с того, что слегка опустите колени и поднимите их, чтобы на короткое время разгрузить штангу. Опускайтесь под перекладину, поднимая ее над головой, когда вы полностью приседаете.","Встаньте в полный рост."],"fe_977428f5":["Используйте для этого упражнения тяжелую сумку. Примите вертикальное положение рядом с сумкой, расставив ноги в шахматном порядке и довольно широко расставив ноги. Положите руку на сумку примерно на уровне груди. Это будет ваше исходное положение.","Начните с скручивания в талии, подталкивая сумку вперед как можно сильнее. Выполняйте это движение быстро, отталкивая сумку от своего тела.","Примите сумку, когда она откидывается назад, выполнив следующие действия в обратном порядке."],"fe_86c3bc53":["Встаньте на четвереньки на земле. Сохраняя правильную осанку, поднимите одно согнутое колено от земли. Это будет ваше исходное положение.","Удерживая колено в согнутом положении, поверните бедро по дуге, пытаясь сделать коленом большой круг.","Проделайте это медленно в течение нескольких повторений и повторите с другой стороны."],"fe_7f2f9279":["Закрепите один конец ленты внизу стойки, второй — на одной лодыжке.","Стоя лицом к месту крепления ленты, держитесь за колонну, чтобы стабилизировать себя.","Держа голову и грудь поднятыми, отведите ногу с сопротивлением назад как можно дальше, сохраняя колено прямым.","Верните ногу в исходное положение."],"fe_1156afc8":["Закрепите один конец ленты внизу стойки, второй — на одной лодыжке.","Отверните лицевую сторону от места крепления ленты.","Держа голову и грудь поднятыми, поднимите колено на 90 градусов и сделайте паузу.","Верните ногу в исходное положение."],"fe_193d396e":["Лягте на спину и подтяните оба колена к груди.","Держите руки под коленями, а не над ними (это окажет сильное давление на ваши коленные суставы).","Медленно подтяните колени к плечам. Это также растянет мышцы ягодиц."],"fe_a78a55d1":["Установите ряд барьеров или других небольших преград, расположив их на расстоянии около метра друг от друга.","Встаньте перед первым препятствием, ноги на ширине плеч. Это будет ваша исходная позиция.","Начните с прыжка обеими ногами через первое препятствие, размахивая обеими руками во время прыжка.","Смягчите удар при приземлении, согнув колени, и отскочите от первого прыжка, перепрыгнув через следующее препятствие. Продолжайте, пока не перепрыгнете все препятствия."],"fe_cfe25ffe":["Обмотайте одну ногу ремнем, веревкой или бандажом и перекиньте эту ногу через туловище в противоположную сторону, держа ногу вытянутой, когда вы лежите на земле. Это будет ваше исходное положение.","Отрывая ногу от пола, потяните за ремень, используя натяжение, чтобы поднять пальцы ног вверх. Задержитесь на 10-20 секунд и повторите упражнение с другой стороны."],"fe_50f4f201":["Лягте на бок, положив нижнюю ногу на поролоновый валик между бедром и коленом. Другую ногу можно скрестить перед собой.","Перенесите максимально возможный вес тела на голень; нет необходимости удерживать голень в контакте с полом. Обязательно расслабьте мышцы ноги, которую вы растягиваете.","Перекатывайте ногу по пенопласту от бедра к колену, задерживаясь на 10-30 секунд в точках напряжения. Повторите то же самое с противоположной ногой."],"fe_326d844c":["Возьмите по гантели в каждую руку и лягте лицом вниз на наклонную скамью, угол наклона которой составляет примерно 30 градусов.","Полностью вытянутые руки должны свисать по бокам так, чтобы они были направлены к полу.","Поворачивайте запястья до тех пор, пока ваши руки не окажутся в проницированном положении (ладонями вниз).","Теперь разведите локти в стороны. Это будет ваше исходное положение.","На выдохе начинайте поднимать гантели вверх, как будто вы выполняете обратный жим лежа. Для этого согните руки в локтях и поднимите их вверх, позволяя предплечьям повиснуть. Продолжайте это движение, пока плечи не окажутся на одном уровне со спиной. Совет: Локти разведите в стороны, а плечи и туловище должны образовать букву «Т» в верхней точке движения. Задержите сжатие в верхней точке на секунду.","На вдохе медленно вернитесь в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_6019f4aa":["Лягте на спину, вытянув ноги. Оберните вокруг ступни ремень, веревку или бандаж и отведите эту ногу как можно дальше в сторону. Это будет ваше исходное положение.","Слегка потяните за ремень, чтобы создать напряжение в паху и мышцах подколенного сухожилия. Задержитесь на 10-20 секунд и повторите упражнение с другой стороны."],"fe_3e63999f":["Обмотайте ленту вокруг столба. Лента должна быть на высоте вашего локтя. Встаньте правым боком к ленте на расстоянии пары футов.","Возьмитесь за конец ленты правой рукой, плотно прижав локоть к боку. Рекомендуем подложить под локоть валик, чтобы зафиксировать его положение.","При таком положении предплечья локоть должен быть согнут на 90 градусов, а кисть должна быть отведена от туловища. Это будет ваше исходное положение.","Выполните это движение, вращая рукой в направлении удара справа, удерживая локоть на месте.","Продолжайте, насколько возможно, задержитесь и вернитесь в исходное положение."],"fe_b281bc41":["Держа голову и шею в нейтральном положении (нормальное положение, когда голова прямо направлена вперед), положите обе руки на переднюю часть головы.","Теперь, сокращая мышцы шеи, слегка надавите вперед, но не поворачивайте голову. Начните с медленного напряжения и постепенно увеличивайте его. При выполнении этого сокращения продолжайте дышать нормально.","Удерживайте рекомендованное количество секунд.","Теперь медленно расслабьте натяжение.","Отдохните рекомендуемое количество времени и повторите упражнение, положив руки на затылок."],"fe_415256f8":["Держа голову и шею в нейтральном положении (нормальное положение, когда голова прямо направлена вперед), положите левую руку на левую сторону головы.","Теперь слегка надавите влево, сокращая левую мышцу шеи, но не допуская движения головы. Начните с медленного напряжения и постепенно увеличивайте его. При выполнении этого сокращения продолжайте дышать нормально.","Удерживайте рекомендованное количество секунд.","Теперь медленно расслабьте натяжение.","Отдохните рекомендуемое количество времени и повторите упражнение, положив правую руку на правую сторону головы."],"fe_03d624a1":["Это упражнение поможет вам научиться опускаться достаточно низко во время рывка и исправит ошибки тех, кто отклоняется назад во время движения. Начните с того, что поднимите штангу в положении рывка, плечи направлены вперед, туловище выпрямлено, а ноги слегка разведены в стороны.","Начните движение так, как если бы вы выполняли обычный рывок, опускаясь в коленях, сохраняя туловище вертикальным, и с силой поднимайтесь назад, используя инерцию, а не руки, чтобы поднять вес.","Удерживайте заднюю ногу на месте, используя ее для движения туловища вперед в полном шпагате, когда вы переносите вес. Восстановитесь, встав с отягощением над головой."],"fe_8b285fa6":["Для заброса бочек разложите нужное количество бочек на некотором удалении от помоста, обычно 9–15 метров.","Начните с захвата ближней рукояти первой бочки, наклонив её набок, чтобы взяться за противоположный край дна. Поднимите бочку к груди.","Чем выше вы держите бочку, тем быстрее сможете двигаться к помосту. Заброс на плечо обычно запрещён. Крепко держите бочку. Двигайтесь к помосту как можно быстрее и закиньте её, разгибаясь в тазобедренных суставах, коленях и голеностопах, чтобы поднять как можно выше.","Вернитесь за следующей бочкой и повторяйте, пока не завершите упражнение."],"fe_33d91e6d":["Положите гирю между стопами. Чтобы занять исходное положение, отведите таз назад и смотрите прямо перед собой.","Поднимите гирю к плечу. Поднимите гирю к плечам, вытягивая ноги и бедра, когда поднимаете гирю к плечу. При этом запястье должно вращаться.","Опустите гирю, сохраняя нагрузку на подколенные сухожилия, держа спину прямой, а ягодицы вытянутыми."],"fe_c52488b3":["Встаньте ровно, стопы на ширине таза. Держите гирю перевёрнутой за «рожки», ядро над кистями, близко к груди. Напрягите пресс и ягодицы, чтобы рёбра оставались опущенными. Это исходное положение.","Держа локти близко к голове, поднимите гирю над одним ухом и заведите за голову.","Продолжайте описывать круг мимо противоположного уха и вернитесь в исходное положение перед грудью, позволяя колокольчику проходить близко к вашему телу.","Выполните предписанное количество кругов в одном направлении, затем повторите то же количество в противоположном направлении.","Двигайтесь медленно, не двигая головой, бедрами и поясницей. Если ваша поясница выгибается дугой или штанга находится далеко от головы, используйте более легкий вес."],"fe_d094d96f":["Встаньте ровно, стопы на ширине таза. Держите гирю перевёрнутой за «рожки», ядро над кистями, близко к груди. Напрягите пресс и ягодицы, чтобы рёбра оставались опущенными. Это исходное положение.","Прижимая локти к голове, поднимите гирю выше одного уха и поворачивайте ее, пока она не окажется у вас за головой. Здесь сделайте паузу.","Из этого положения вытяните локти и поднимите гирю вверх и над головой до тех пор, пока ваши руки не станут прямыми, держа предплечья на уровне головы.","Согните руки в локтях, чтобы под контролем опустить гирю обратно в исходное положение за головой.","Продолжайте описывать круг над противоположным ухом и вернитесь в исходное положение перед грудью, чтобы выполнить одно повторение.","При каждом повторении меняйте направление движения по кругу. Держите голову, бедра и нижнюю часть спины неподвижными; если ваша поясница выгибается дугой или вы не можете принять положение над головой, не откидываясь назад, используйте более легкий вес или выполняйте гало и разгибание как отдельные упражнения."],"fe_d58993f3":["Возьмите гирю за ручку в одну руку. Встаньте на одну ногу с той стороны, с которой вы держите гирю.","Держа колено слегка согнутым, выполните становую тягу на негнущихся ногах, сгибаясь в бедре и вытягивая свободную ногу за собой для равновесия.","Продолжайте опускать гирю до тех пор, пока она не окажется параллельна земле, а затем вернитесь в вертикальное положение."],"fe_050fc8e8":["Встаньте, расставив ноги на ширину бедер, держа гирю за рога обеими руками. Поднимите гирю над головой так, чтобы руки были вытянуты вперед, а гиря висела у вас за ладонями.","Напрягите мышцы брюшного пресса и держите плечи вертикально и близко к голове. Это ваше исходное положение.","Согните руки в локтях, чтобы опустить гирю за голову, насколько позволяет подвижность плеч, но при этом локти не должны быть направлены наружу.","Вытяните локти, чтобы вернуть гирю в исходное положение, сохраняя предплечья неподвижными.","Держите грудную клетку опущенной и старайтесь не выгибать нижнюю часть спины при разгибании."],"fe_8e29091d":["Поставьте одну гирю между ног и примите удобную позу. Наклонитесь, выпятив ягодицы и держа спину ровно.","Возьмите гирю и переложите ее в другую руку, расположив между ног, в виде буквы «W». Сделайте несколько повторений вперед и назад."],"fe_bf84b238":["Стоя в широкой стойке, возьмите гирю обеими руками. Держите ее на вытянутых руках на уровне талии. Это будет ваше исходное положение.","Начните движение с поворота в одну сторону, поднимая гирю на высоту головы. В начале движения сделайте короткую паузу.","Позвольте гири опуститься, когда вы поворачиваетесь в противоположную сторону, снова поднимая гирю на высоту головы.","Повторите упражнение желаемым количеством раз."],"fe_9cd4d40e":["Лягте на пол, выпрямив правую ногу. Согните левую ногу и опустите ее поперек туловища, прижимая колено к полу правой рукой. (Если вы напряжены, колено не должно касаться пола).","Расположите левую руку поудобнее рядом с собой и поверните голову влево. Представьте, что к копчику привязан груз. пусть копчик опустится к полу, а грудная клетка потянется в противоположном направлении, чтобы растянуть поясницу. Поменяйтесь сторонами."],"fe_c0bd86b2":["Начните с удобного положения стоя, слегка согнув колени. Вытяните руки перед собой ладонями вниз, соединив кончики пальцев на уровне груди. Это будет ваше исходное положение.","Быстро опуститесь на четвереньки и сразу же резко поднимитесь вверх. Подтяните колени к груди, стараясь коснуться ими ладоней.","Подпрыгните как можно выше, поднимая колени вверх, а затем, чтобы обеспечить хорошую посадку, снова вытяните ноги, поглощая удар и позволяя коленям разогнуться."],"fe_3e751df2":["Подсоедините веревочное крепление к высокому тросу шкива и расстелите на полу перед ним коврик.","Возьмитесь за веревку обеими руками и встаньте на колени примерно в двух футах от башни.","Заведите веревку за голову, держа руки у ушей.","Держите руки на одном и том же месте, напрягите пресс и потягивайтесь за скакалку вниз с хрустом, пока локти не достигнут колен.","Сделайте короткую паузу внизу и поднимайтесь медленно и контролируемо, пока не достигнете исходного положения.","Повторяйте то же движение вниз, пока не опуститесь наполовину, и в это время начните поворачивать один из локтей к противоположному колену.","Снова сделайте короткую паузу внизу и поднимайтесь медленно и контролируемо, пока не достигнете исходного положения.","Повторите то же движение, что и раньше, но поочередно прикладывайте другой локоть к противоположному колену.","Продолжайте эту серию движений до отказа."],"fe_2620801f":["Начните с того, что встаньте на колени на коврике так, чтобы ладони были прижаты друг к другу, а пальцы направлены назад к коленям.","Медленно отклоняйтесь назад, не отрывая ладоней от пола, пока не почувствуете растяжение в запястьях и предплечьях. Задержитесь на 20-30 секунд."],"fe_ca6cb927":["Встаньте на колени на коврик и поднимите правое колено так, чтобы нижняя часть стопы была на полу, а левую ногу вытяните за собой так, чтобы верхняя часть стопы была на полу.","Переносите вес тела вперед, пока не почувствуете растяжение в бедре. Задержитесь на 15 секунд, затем повторите упражнение для другой стороны."],"fe_22aff575":["Прикрепите одну ручку к высокому шкиву и выберите нужный вес.","Встаньте на колени перед кабельной вышкой, держась за трос одной рукой на вытянутой руке. Это будет ваше исходное положение.","Начиная с того, что ваша ладонь направлена вперед, перенесите вес тела на туловище, сгибая локоть и втягивая лопатку. При этом поверните запястье так, чтобы в конце движения ваша ладонь была обращена к вам.","После короткой паузы вернитесь в исходное положение."],"fe_8778fec6":["Установите штангу на мину или, при ее отсутствии, надежно закрепите ее в углу. Установите штангу на соответствующий вес и закрепите рукоятку на штанге.","Поднимите штангу от пола, прижав рукоятки к плечам. Это будет ваше исходное положение.","Приняв спортивную стойку, присядьте на корточки, сгибая бедра и отводя их назад, держа руки согнутыми.","Повторите движение в обратном направлении, мощно разгибая бедра, колени и лодыжки, одновременно разгибая локти, чтобы выпрямить руки. Это движение следует выполнять взрывным движением, поднимаясь из приседа до полного разгибания с максимально возможной силой.","Вернитесь в исходное положение."],"fe_28fd27fa":["Примите положение полуприседа, повернувшись лицом под углом 90 градусов к направлению вашего движения. Это будет ваше исходное положение.","Позвольте ведущей ноге сделать встречное движение внутрь, перенося вес тела на внешнюю ногу.","Немедленно оттолкнитесь и вытянитесь, стараясь отклониться в сторону как можно дальше.","Приземлившись, немедленно оттолкнитесь в противоположном направлении, возвращаясь в исходное положение.","Продолжайте движение взад-вперед в течение нескольких повторений."],"fe_40c0944b":["Примите удобное положение стоя, поставив рядом с собой короткий ящик. Это будет ваше исходное положение.","Быстро опуститесь на четверть приседа, чтобы вызвать рефлекс растяжки, и немедленно измените направление, чтобы подпрыгнуть вверх и в сторону.","Поднимите колени достаточно высоко, чтобы ваши ступни располагались на достаточном расстоянии от коробки.","Приземляйтесь на центр поля, используя ноги, чтобы смягчить удар.","Осторожно перепрыгните на другую сторону ящика и продолжайте движение взад-вперед в течение нескольких повторений."],"fe_468f06ae":["Расположите несколько конусов в ряд на расстоянии около метра друг от друга.","Встаньте рядом с концами конусов, повернувшись лицом под углом 90 градусов к направлению движения. Это будет ваша исходная позиция.","Начните прыжок с опускания коленей, чтобы вызвать рефлекс растяжения, и немедленно измените направление, чтобы оттолкнуться от земли, прыгая вверх и вбок через конус.","Используйте свои ноги, чтобы смягчить удар при приземлении, и отскакивайте для следующего прыжка, продолжая спускаться по ряду конусов."],"fe_550812ad":["Лежа на полу, подложите под спину и в сторону, сразу за подмышками, пенопластовый валик. Это будет ваше исходное положение.","При переносе веса тела на широчайшие мышцы держите руки вытянутыми назад и в сторону от себя, отрывая верхнюю часть туловища от пола. Задержитесь на 10-30 секунд, затем поменяйте положение."],"fe_25d7ca40":["Лягте на пол, прижав одну гирю к груди и держа ее за ручку. Вытяните ногу на рабочей стороне над ногой на нерабочей стороне.Свободную руку можно вытянуть в сторону для опоры.","Установите гирю в зафиксированное положение.","Опускайте вес до тех пор, пока локоть не коснется земли, удерживая гирю над локтем. Повторите желаемое количество раз."],"fe_ecf0a29a":["Стоя прямо, поставив обе ноги рядом друг с другом примерно на ширине плеч, возьмитесь за прочную поверхность, например, за боковые стороны стойки для приседаний или за спинку стула, чтобы подтянуться и сохранить равновесие.","С отягощением на лодыжке или без него поднимите одну ногу за собой, как будто выполняете скручивание, но стоя, сохраняя другую ногу прямой. При выполнении этого движения сделайте выдох.","На вдохе медленно опустите поднятую ногу обратно на пол.","Повторите рекомендуемое количество повторений.","Повторите движение противоположной ногой."],"fe_f953df0f":["Лягте на коврик для упражнений, вытянув ноги и положив руки либо ладонями вниз рядом с собой, либо под ягодицами. Совет: Я предпочитаю, чтобы руки были рядом со мной. Это будет ваше исходное положение.","На выдохе согните ноги в коленях и подтяните верхнюю часть бедер к животу. Продолжайте движение, пока колени не окажутся на уровне груди. Напрягите мышцы пресса, выполняя это движение, и задержитесь на секунду в верхней точке. Совет: Когда вы выполняете это движение, голени (икры) всегда должны оставаться параллельными полу.","На вдохе вернитесь в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_f9d54bcc":["Установите на штифты соответствующий груз и отрегулируйте высоту сиденья таким образом, чтобы ручки находились на уровне груди. Возьмитесь за ручки нейтральным или наклонным хватом. Это будет ваше исходное положение.","Тяните рукояти к корпусу, сводя лопатки и сгибая локти.","Сделайте паузу в конце движения, а затем медленно верните рукоятки в исходное положение. При многократных повторениях старайтесь не возвращать вес полностью к упорам, чтобы сохранить напряжение в прорабатываемых мышцах."],"fe_c150419e":["Вам понадобятся два ящика или скамейки, расположенные на расстоянии около метра друг от друга. Для начала встаньте на один ящик лицом к другой платформе.","Чтобы начать движение, мягко опуститесь на землю между вашими платформами, позволяя коленям и бедрам согнуться.","Повторите движение в обратном направлении, напрягая бедра, колени и лодыжки, чтобы перепрыгнуть на другую платформу.","Приземляйтесь мягко, амортизируя удар ногами."],"fe_e29aa012":["Встаньте с логом перед собой. Возьмитесь за рукояти и начните взятие лога. В наклоне в начале взятия старайтесь поднять лог как можно выше, подтягивая его к груди. Разгибайтесь в тазобедренных суставах и коленях, чтобы завершить взятие.","Отведите голову назад и поднимите взгляд, образуя полку грудью для лога. Начните жим с подседа: слегка согнув колени, обратите движение вспять. Этот швунг даст инерцию, чтобы сдвинуть лог вертикально вверх. Затем разгибайте локти, выжимая лог над головой. Строгих правил техники нет — используйте то, что вам эффективнее. На каждом повторении при жиме выводите голову вперёд, глядя вперёд.","Повторяйте как можно больше раз. Постарайтесь контролировать опускание лога на пол."],"fe_5c1dc150":["Встаньте на колени на пол, держась за пятки обеими руками.","Поднимите ягодицы вверх и вперед, одновременно запрокидывая голову назад, чтобы посмотреть на потолок, и выгните спину дугой."],"fe_0d8cd7c1":["Сядьте на станок с низким расположением шкивов и закрепите его тросом.","Возьмитесь за концы веревки ладонями вниз и сядьте, выпрямив спину и слегка согнув колени. Совет: Держите спину почти полностью вертикально, а руки полностью вытянутыми перед собой. Это будет ваше исходное положение.","Сохраняя туловище неподвижным, поднимите локти и начинайте сгибать их, одновременно подтягивая веревку к шее на выдохе. На протяжении всего движения плечи должны оставаться параллельными полу. Совет: Продолжайте это движение до тех пор, пока ваши ладони не окажутся почти рядом с ушами (в конце движения предплечья не будут параллельны полу, так как они будут немного повернуты вверх), а локти не будут разведены в стороны.","Задержавшись примерно на секунду в согнутом положении, на вдохе медленно вернитесь в исходное положение. Совет: Еще раз повторю, ни в коем случае во время выполнения движения туловище не должно двигаться.","Повторите рекомендуемое количество повторений."],"fe_6736dea8":["В положении сидя подложите под поясницу пенопластовый валик. Скрестите руки перед собой и расправьте плечи. Это будет ваше исходное положение.","Оторвите бедра от пола и отклонитесь назад, перенося вес тела на поясницу. Теперь слегка сместите вес тела в сторону, стараясь, чтобы вес тела приходился не на позвоночник, а на боковые мышцы. Перекатитесь на поясницу, удерживая точки напряжения в течение 10-30 секунд. Повторите упражнение с другой стороны."],"fe_c32a75f2":["Лягте на спину, согнув ноги в коленях и прижав ступни друг к другу. Попросите партнера держать вас за колени. Это будет ваше исходное положение.","Попытайтесь сжать колени вместе, в то время как ваш партнер будет препятствовать любым движениям.","Через 10-20 секунд расслабьте мышцы, пока ваш партнер мягко прижимает ваши колени к полу. Обязательно сообщите своему помощнику, когда растяжка будет достаточной, чтобы предотвратить травму или перенапряжение."],"fe_9e62bc69":["Установите плоскую скамью перед высоким шкивом или станком для натяжения лат.","Возьмитесь за крепление прямой штанги нижним хватом (ладонями вверх) примерно на ширине плеч.","Лягте на спину, положив голову на край скамьи.","Теперь вытяните руки прямо над плечами. Ваш торс и руки должны составлять угол в 90 градусов, а локти должны быть согнуты. Это будет ваше исходное положение.","На выдохе опускайте штангу полукруглыми движениями, пока она не коснется вашего подбородка. На секунду напрягите бицепсы в верхнем сжатом положении. Совет: При выполнении этого движения должны двигаться только предплечья. Ни в коем случае не двигайте предплечьями. Они должны оставаться перпендикулярными на протяжении всего движения.","Медленно вернитесь в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_f6d74824":["Лягте на спину, вытянув ноги.","Скрестите одну ногу над туловищем, согнув ее в колене, стараясь коснуться коленом пола. Ваш партнер должен встать на колени рядом с вами, одной рукой прижимая ваше плечо к полу, а другой контролируя скрещенную ногу. это будет ваше исходное положение.","Попытайтесь оторвать согнутое колено от земли, так как ваш партнер мешает вам сделать какое-либо движение.","Через 10-20 секунд расслабьте ногу, в то время как ваш партнер мягко прижимает колено к полу. Повторите с другой стороны."],"fe_4dd9522f":["Лягте лицом вниз, выпрямив все тело, на плоскую скамью, держа гантель за головой. Совет: Вам нужно расположиться так, чтобы ваши плечи были немного выше края плоской скамьи, чтобы верхняя часть груди, шея и лицо находились над скамьей. Это будет ваша исходная позиция.","Удерживая пластину на затылке, медленно опускайте голову (как при произнесении «да») на вдохе.","Верните голову в исходное положение полукруглым движением на выдохе. Задержите сокращение на секунду.","Повторите рекомендуемое количество повторений."],"fe_6888c3d9":["Лягте на спину, а ваш партнер встаньте на колени рядом с вами.","Согните бедро одной ноги, отрывая его от пола. Поверните ногу так, чтобы стопа находилась на противоположном бедре, а голень была перпендикулярна вашему телу. Ваш партнер должен удерживать колено и лодыжку на месте. Это будет ваше исходное положение.","Попытайтесь подтолкнуть свою ногу к партнеру, который должен препятствовать любому действительному движению ноги.","Через 10-20 секунд полностью расслабьтесь, когда ваш партнер мягко подтянет лодыжку и колено к вашей груди. Обязательно сообщите своему помощнику, когда растяжка будет достаточной, чтобы предотвратить травму или перенапряжение."],"fe_a91f74c4":["Лягте на спину, вытянув ноги. Ваш партнер должен стоять на коленях рядом с вами. Поднимите одну ногу к потолку и попросите партнера взять ее за лодыжку. При необходимости ваш партнер может опереться плечом на вашу ногу. Это будет ваше исходное положение.","Пока ваш партнер удерживает вашу ногу на месте, попытайтесь согнуть ее в колене, напрягая подколенные сухожилия в течение 10-20 секунд.","Затем расслабьте ногу, позволяя партнеру слегка подтолкнуть ее к вашей голове. Обязательно сообщите своему помощнику, когда растяжка будет достаточной, чтобы предотвратить травму или перенапряжение. После завершения упражнения поменяйтесь сторонами."],"fe_f5f2821b":["Лягте лицом вперед на высокую плоскую скамью, держа штангу в положении лежа на спине (ладони обращены вверх). Совет: Если вы держите штангу, возьмите ее на ширине плеч, а если вы используете перекладину E-Z, возьмите ее за внутренние ручки. Ваша верхняя часть тела должна располагаться таким образом, чтобы верхняя часть грудной клетки находилась над краем скамьи, а штанга висела перед вами, руки были вытянуты и перпендикулярны полу. Это будет ваше исходное положение.","Удерживая локти согнутыми, а плечи неподвижными, поднимите вес тела полукруглыми движениями, одновременно напрягая бицепсы и выдыхая. Задержитесь в верхней точке движения на секунду.","На вдохе медленно вернитесь в исходное положение. Совет: Все время полностью контролируйте вес и избегайте раскачиваний. Помните, что во время движения должны двигаться только предплечья.","Повторите рекомендуемое количество повторений."],"fe_9501b3a9":["Лягте лицом вниз на пол, а ваш партнер встаньте на колени рядом с вами. Согните одну ногу в колене и поднимите ее от пола, стараясь коснуться стопой ягодиц. Ваш партнер должен поддерживать колено и лодыжку. Это будет ваше исходное положение.","Попытайтесь выпрямить колено, в то время как ваш партнер препятствует любому реальному движению.","Через 10-20 секунд расслабьте мышцы, когда ваш партнер мягко подтолкнет стопу к вашим ягодицам, еще больше растягивая четырехглавую мышцу и сгибатели бедра.","Через 10-20 секунд поменяйтесь сторонами."],"fe_f1d51a49":["Для выполнения этого упражнения вам понадобится медицинский мяч и партнер. Встаньте спиной к спине со своим партнером на расстоянии 2-3 футов друг от друга. Это будет ваша исходная позиция.","Держите мяч перед туловищем. Разведите бедра и разверните плечи одновременно с вашим партнером.","Для полного вращения вы и ваш партнер должны вращаться в одном направлении, то есть против часовой стрелки.","Передайте мяч своему партнеру, и теперь вы оба можете покрутиться в противоположном направлении, чтобы повторить процедуру."],"fe_9da0ddb7":["Лягте лицом вниз на наклонную скамью, держа по гантели в каждой руке. Ваши руки должны быть полностью вытянуты и направлены вниз, к полу. Ладони должны быть обращены друг к другу. Это будет ваше исходное положение.","На выдохе сведите лопатки вместе и удерживайте их в таком положении целую секунду. Совет: Это движение похоже на обратное действие объятия или на попытку выполнить боковые движения сзади, как если бы у вас не было рук.","На вдохе вернитесь в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_c804d7d5":["Встаньте так, чтобы ноги были на ширине плеч, а руки — на бедрах.","Сгибайтесь в талии, пока не почувствуете растяжение. Задержитесь на 10-15 секунд, затем повернитесь в другую сторону."],"fe_b8f4c30d":["Используя расстояние, которое примерно на 1 дюйм больше ширины плеч, возьмитесь за перекладину так, чтобы ладони одной руки были обращены вперед, а ладони другой — к себе. Это будет ваше исходное положение.","Теперь начинайте подтягиваться на выдохе. Совет: При выполнении движения руками, обращенными ладонями вверх, сосредоточьтесь на использовании мышц спины. Локоть этой руки должен оставаться прижатым к туловищу. Другой рукой, ладони которой обращены вперед, локти должны быть разведены в стороны, но находиться на одной линии с туловищем. Вы сосредоточитесь на том, чтобы с помощью широких мышц подтягивать свое тело вверх.","После второго сокращения в верхней точке начинайте медленно опускаться на вдохе.","Повторите рекомендуемое количество повторений.","В следующем подходе поменяйтесь захватами; таким образом, если вы держали правую руку ладонями к себе, а левую — ладонями вперед, то в следующем подходе у вас будут ладони, обращенные вперед, для правой руки и обращенные к вам для левой."],"fe_eb2bbf53":["Начните с гантели с нагрузкой, удерживая ее широким хватом на уровне середины бедер. Ступни должны быть прямо под бедрами, при этом стопы должны быть развернуты по мере необходимости. Опустите бедра, грудь приподнята, а голова направлена вперед. Плечи должны находиться прямо перед перекладиной. Это и будет исходное положение.","Начните подтягивание с движения пятками вперед, поднимая штангу. Переходите ко второму подтягиванию, разгибая бедра, колени и лодыжки, поднимая штангу как можно быстрее. Штанга должна находиться близко к телу.","Продолжайте поднимать штангу в положение над головой, не разгибая коленей."],"fe_dee34fb2":["Обоприте спину на спинку тренажёра и заведите плечи под валики.","Поставьте ноги на платформу так, чтобы они были на ширине плеч, слегка расставив носки. Расстояние между ступнями должно составлять не более 3 дюймов. Совет: Все время держите голову высоко поднятой, а спину — на подушечке.","Возьмитесь за боковые рукояти тренажёра и снимите предохранительные упоры (в большинстве конструкций — переводом боковых рукоятей из переднего положения в диагональное).","Теперь выпрямите ноги, не сгибая их в коленях. Это будет ваше исходное положение.","Начинайте медленно опускать устройство, сгибая ноги в коленях и сохраняя прямую осанку с поднятой головой (все время опираясь спиной о подушку). Продолжайте опускаться, пока угол между верхней частью ноги и икрами не станет чуть меньше 90 градусов (это точка, в которой верхняя часть ног находится ниже параллели с полом). Выполняя эту часть движения, сделайте вдох.","На выдохе начинайте поднимать тренажер, отталкиваясь от пола, главным образом, пятками ног, затем снова выпрямляйте ноги и возвращайтесь в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_ab72d637":["Используя тренажер для жима ногами, сядьте на него и поставьте ноги на платформу прямо перед собой на ширине плеч, слегка расставив носки. Ваши ступни должны находиться на расстоянии около 3 дюймов друг от друга или меньше. Совет: Все время держите голову высоко поднятой, а спину — на подушечке.","Опустите предохранительные упоры платформы и выжмите платформу вверх до полного выпрямления ног. Совет: не блокируйте колени. Корпус и ноги должны образовывать прямой угол 90 градусов. Это исходное положение.","На вдохе медленно опустите платформу, пока между бёдрами и голенями не образуется угол 90 градусов.","Отталкиваясь в основном пятками и усилием квадрицепсов, вернитесь в исходное положение на выдохе.","Повторите рекомендуемое количество повторений и обязательно зафиксируйте предохранительные штыри по завершении: нагруженная платформа не должна упасть на вас."],"fe_fddd840b":["Используя мышечный валик или скалку, поместите его за голову и прижмите к шее. Убедитесь, что вы не прижимаете валик непосредственно к позвоночнику, а слегка повернули его так, чтобы он был прижат к мышцам по обе стороны от позвоночника. Это будет ваше исходное положение.","Начиная с верхней части шеи, медленно двигайте мышцами шеи вниз, задерживаясь в местах наибольшего напряжения на 10-30 секунд."],"fe_b808300c":["Лягте спиной на плоскую скамью. Используя хват средней ширины (хват, который создает угол в 90 градусов в середине движения между предплечьями и плечами), поднимите штангу со стойки и держите ее прямо над шеей, сцепив руки в замок. Это будет ваша исходная позиция.","На вдохе медленно опускайтесь вниз, пока не почувствуете перекладину на своей шее.","После секундной паузы верните штангу в исходное положение на выдохе, выжимая её грудными мышцами. Зафиксируйте руки и напрягите грудь в сокращённом положении, задержитесь на секунду и снова начинайте медленно опускать. Совет: опускание должно занимать как минимум вдвое больше времени, чем подъём.","Повторите движение предписанное количество повторений.","По завершении верните штангу на стойки."],"fe_ca195b1e":["Лягте на плоскую скамью или ступеньку и свесьте одну ногу и руку через борт.","Согните ногу в колене и возьмитесь за верхнюю часть стопы. При выполнении этого упражнения следите за тем, чтобы поясница не выгибалась дугой.","Подтяните пупок к позвоночнику, чтобы он оставался в нейтральном положении. Опустите стопу вниз и прижмите ее к ладони. Чтобы усилить растяжку бедра, поднимите бедро ноги, которую вы держите, к потолку.","Смените сторону."],"fe_8d841121":["Подсоедините стандартную рукоятку к башне. Переместите трос в самое верхнее положение шкива.","Встаньте боком к тросу. Одной рукой поднимитесь и возьмитесь за ручку снизу.","Потяните вниз трос до тех пор, пока локоть не коснется вашего бока, а ручка не окажется у вашего плеча.","Поставьте ноги на ширину бедер. Положите свободную руку на бедро, чтобы определить точку поворота.","Держите руку в статичном положении. Наклонитесь, чтобы перенести вес тела на бок.","Как только вы достигнете максимального напряжения, медленно верните гантель в исходное положение. Ни в коем случае не разгружайте штангу в исходном положении. Цель — постоянное напряжение во время подхода.","Повторяйте до отказа.","Затем повторите ту же серию движений на противоположной стороне."],"fe_1f8e8468":["Поставьте гирю между ног. Наклоняясь, чтобы взять гирю, отведите ягодицы назад и смотрите прямо перед собой.","Подтяните гирю к плечам, вытягивая ноги и бедра, когда вы поднимаете гирю к плечу. При этом запястье должно вращаться.","Верните вес в исходное положение."],"fe_e881770a":["Установите гриф в лендмайн или в угол, чтобы он не двигался. Навесьте подходящий вес на ваш конец.","Встаньте рядом со штангой и возьмитесь за нее одной рукой рядом с воротником. Используя бедра и ноги, поднимитесь в положение стоя.","Примите стойку с согнутыми коленями, отведите бедра назад и поднимите грудь. Ваша рука должна быть вытянута. Это будет ваше исходное положение.","Отведите вес тела в сторону, отведя плечо и согнув локоть. Не перемещайте вес рывком и не жульничайте во время движения.","После короткой паузы вернитесь в исходное положение."],"fe_4ec719fd":["Поднимите гирю и прижмите ее к плечу одной рукой. Поднимите гирю к плечу, вытягивая ноги и бедра, одновременно подтягивая гирю к плечу. При этом вращайте запястьем. Поднимите гирю над головой, вытягивая локоть.Это будет ваша исходная позиция.","Глядя прямо перед собой и держа гирю на весу, согните колени и бедра и опустите туловище между ног, держа голову и грудь поднятыми.","Задержитесь в нижнем положении на секунду, прежде чем снова подняться в верхнее, двигаясь пятками ног."],"fe_1d24b920":["Закрепите кожаную манжету на лодыжке за низкий тросовый блок, а затем прикрепите манжету к лодыжке.","Встаньте лицом к штабелю с грузом на расстоянии около двух футов, держась за стальную раму для опоры.","Держа колени и бедра слегка согнутыми, а пресс напряженным, напрягите ягодичные мышцы, чтобы медленно «отвести» рабочую ногу назад по полукруглой дуге так высоко, как вам удобно, на выдохе. Совет: При полном разгибании сожмите ягодичные мышцы на секунду, чтобы добиться максимального сокращения.","Теперь медленно выдвиньте рабочую ногу вперед, сопротивляясь натягиванию троса, пока не вернетесь в исходное положение.","Повторите рекомендуемое количество повторений.","Поменяйте ноги и повторите движение в другую сторону."],"fe_8a1410b5":["Лягте на пол лицом вниз.","Положите левую руку под левую тазовую кость, чтобы обхватить бедро и лобковую кость.","Согните правую ногу в колене так, чтобы вы могли держать ступню в правой руке.","Поднимите ногу в воздух и одновременно оторвите плечи от пола. Это также растянет сгибатель правого бедра, а также грудь и плечи. Поменяйтесь местами. Если это не беспокоит вашу спину, вы можете попробовать сделать это обеими руками и ногами одновременно."],"fe_146a662d":["Возьмитесь за перекладину для подтягивания одной рукой, используя проницированный хват. Поставьте ноги на пол или ступеньку. Перенесите основную часть своего веса на эту руку, не отрывая ног от пола. Задержитесь на 10-20 секунд и поменяйтесь местами."],"fe_84579dba":["Начните с того, что лягте на пол.","Вытяните одну ногу прямо, а колено другой подтяните к груди. Согните ее в коленном суставе, чтобы защитить коленную чашечку.","Осторожно подтяните это колено к носу.","Поменяйтесь сторонами. При этом растягиваются ягодицы и поясница согнутой ноги, а также сгибатель бедра прямой ноги."],"fe_4ed63785":["Поставьте одну гирю между ступнями. Вытяните гирю, разминая ноги и бедра, и поднимите ее к плечам.","Отпустите гирю, когда она поднимется, и переверните ее так, чтобы шар гири оказался в ваших ладонях.","Вытяните гирю перед собой и возьмитесь за ручку обеими руками. Опустите гирю в исходное положение и повторите упражнение."],"fe_6577b791":["Сядьте прямо на пол так, чтобы ваш партнер находился позади вас. Поднимите одну руку прямо вверх и согните локоть, стараясь прижать ладонь к спине. Партнер должен держать вас за трицепс и запястье. Это будет ваше исходное положение.","Попытайтесь вытянуть верхнюю часть руки в сторону, так как ваш партнер мешает вам сделать это на самом деле.","Через 10-20 секунд расслабьте руку и позвольте партнеру еще больше растянуть широчайшие мышцы, слегка надавливая на трицепс. Задержитесь на 10-20 секунд, а затем поменяйтесь сторонами."],"fe_2360a42d":["Возьмите мяч обеими руками и встаньте так, чтобы ноги были на ширине плеч. Это будет ваше исходное положение.","Начните встречное движение, подняв мяч над головой и полностью выпрямив тело.","Повторите движение в обратном направлении, изо всех сил ударяя мячом о землю прямо перед собой.","Примите мяч обеими руками на отскок и повторите движение."],"fe_beb68c59":["Подсоедините стандартную ручку к опоре и, если возможно, расположите трос на высоте плеча. Если нет, то достаточно низкого шкива.","Стоя боком к тросу, возьмитесь за рукоятку обеими руками и отойдите от вышки. Вы должны находиться примерно на расстоянии вытянутой руки от шкива, при этом груз должен быть натянут на трос.","Расположив ноги на ширине бедер и слегка согнув колени, держите трос на уровне середины груди. Это будет ваше исходное положение.","Отведите трос от груди, полностью вытянув обе руки. Ваш сердечник должен быть напряжен.","Задержите повторение на несколько секунд, прежде чем вернуться в исходное положение.","В конце подхода повторите упражнение, повернувшись лицом в другую сторону."],"fe_449c5665":["Лягте на бок, перенеся вес тела на предплечье и на поролоновый валик, положенный на внешнюю сторону голени. Верхняя часть ноги может быть либо поверх голени, либо вы можете скрестить ее перед собой. Это будет ваше исходное положение.","Поднимите бедра от пола и начинайте перекатываться от уровня ниже колена к уровню выше лодыжки по боковой поверхности ноги, делая паузы в точках напряжения на 10-30 секунд. Повторите упражнение с другой ногой."],"fe_fe0e3df2":["Лягте на мяч так, чтобы верхняя часть спины находилась на мяче, а бедра не опирались на него. Обе ступни должны стоять ровно на полу, на ширине бедер или шире их. Это будет ваше исходное положение.","Начните с разгибания бедер, используя ягодичные мышцы и подколенные сухожилия, поднимая бедра вверх, когда вы переходите на мостик.","Сделайте паузу в начале движения и вернитесь в исходное положение."],"fe_29a27d0d":["Сядьте ягодицами на поролоновый валик. Согните ноги в коленях, а затем скрестите одну ногу так, чтобы лодыжка оказалась над коленом. Это будет ваше исходное положение.","Перенесите вес тела на скрещенную ногу, перекатываясь через ягодицы, пока не почувствуете напряжение в верхней части ягодичной мышцы. Вы можете облегчить растяжку, подтягивая согнутое колено одной рукой к груди. Задержитесь в этом положении на 10-30 секунд, а затем поменяйтесь сторонами."],"fe_445fb6f4":["Лягте на пол ничком, перенося вес тела на носки и предплечья. Руки согнуты и находятся прямо под плечами.","Все время держите туловище прямо и удерживайте это положение как можно дольше. Для увеличения сложности можно поднять руку или ногу."],"fe_86b20510":["Возьмите две тарелки с широкими бортиками и поставьте их друг на друга гладкими сторонами наружу.","Возьмитесь пальцами за внешнюю часть тарелки, а большим пальцем — за другую сторону, таким образом удерживая обе тарелки вместе. Это исходное положение.","Сожмите пластину двумя пальцами. Удерживайте это положение как можно дольше.","Повторяйте упражнение столько раз, сколько рекомендовано в вашей программе.","Поменяйте руки местами и повторите движения."],"fe_75002120":["Лягте на пол или на коврик для упражнений, полностью вытянув ноги и выпрямив верхнюю часть туловища. Возьмите тарелку за бока обеими руками, расположив их перед брюшным прессом, слегка согнув руки.","Медленно скрестите ноги в районе лодыжек и оторвите их от пола. Колени также должны быть слегка согнуты. Примечание: При выполнении этого упражнения слегка отведите верхнюю часть туловища назад, чтобы сохранить равновесие. Это исходное положение.","Передвиньте тарелку влево и коснитесь ею пола. При выполнении этого движения сделайте выдох.","На вдохе вернитесь в исходное положение, а затем повторите движение, но на этот раз в правую сторону. Совет: Всегда выполняйте медленные контролируемые движения. Резкие движения могут травмировать спину.","Повторите рекомендуемое количество повторений."],"fe_90c145ad":["Для выполнения этого движения необходим деревянный пол или что-то подобное. Лягте на спину, вытянув ноги. Подложите под пятки спортивное полотенце или легкий груз. Это будет ваше исходное положение.","Начните движение с сгибания ноги в колене, держа другую ногу прямой.","Продолжайте подтягивать пятку ближе к себе, скользя ею по полу.","При полном сгибании колена выполните обратное движение, чтобы вернуться в исходное положение."],"fe_3eca1437":["Возьмите гантель обеими руками за основание и встаньте прямо. Расставьте ноги так, чтобы они были шире ширины плеч, слегка согнув их в коленях.","Пальцы ног должны быть направлены наружу. Примечание: Во время выполнения упражнения ваши руки должны быть неподвижны. Это исходное положение.","Медленно согните ноги в коленях и опустите их так, чтобы бедра были параллельны полу. Обязательно делайте вдох, так как это самая эксцентричная часть упражнения.","На выдохе надавливайте главным образом пяткой стопы, чтобы вернуть тело в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_6ee93643":["Расположив штангу на ящиках нужной высоты, возьмитесь за нее хватом снаружи ног. Опустите бедра так, чтобы вес был сосредоточен на пятках, спина прямая, голова направлена вперед, грудь приподнята, плечи находятся прямо перед перекладиной. Это будет ваше исходное положение.","Начните первый рывок с движения пятками, разгибая колени. Угол наклона спины должен оставаться прежним, а руки — прямыми. Когда штанга достигнет середины бедра, начинайте разгибаться за счет бедер.","Выполняя прыжковое движение, ускоряйтесь, разгибая бедра, колени и лодыжки, используя скорость для поднятия штанги вверх. Не должно быть необходимости активно вытягивать руки, чтобы увеличить вес. В конце второго рывка туловище должно быть полностью выпрямлено, слегка отклонено назад, руки по-прежнему вытянуты.","Когда вы достигнете полного разгибания, переходите к третьему подтягиванию, энергично пожимая плечами и сгибая руки в локтях вверх и в стороны. При максимальном разгибании подтягивайтесь под перекладиной настолько, чтобы ее можно было положить на плечи, вращая при этом локтями под перекладиной. Штангу следует переносить на вытянутые плечи, слегка касаясь горла расслабленными руками.","Немедленно восстановите равновесие, отталкиваясь пятками, держа туловище вертикально, а локти поднятыми. Продолжайте, пока не встанете в положение стоя, и завершите повторение, вернув вес на боксы."],"fe_bd3da88e":["Стоя, перенеся вес тела на переднюю поверхность плеч, начните с опускания. Поставьте ступни прямо под бедра, согните колени, не отводя бедра назад. Опускайтесь совсем немного и как можно сильнее меняйте направление.","Отталкиваясь пятками, создайте максимальную скорость и силу и обязательно уберите голову с траектории, когда штанга покидает плечи.","В тот момент, когда ступни отрываются от пола, их необходимо как можно быстрее поставить в исходное положение. В тот короткий момент, когда ступни не будут активно упираться в платформу, усилие спортсмена, направленное на поднятие штанги, приведет к их опусканию. Ноги должны быть расставлены немного шире, колени частично согнуты.","Примите штангу так, чтобы руки были вытянуты над головой.","Встаньте в полный рост."],"fe_6ff053b3":["Встаньте, корпус вертикально, по гантели в опущенных руках. Локти близко к корпусу.","Ладони рук должны быть обращены к туловищу. Ваши ноги должны быть примерно на ширине плеч. Это будет ваше исходное положение.","Держа руки прямыми, а туловище неподвижным, на выдохе поднимайте гантели в стороны до тех пор, пока они не окажутся примерно на уровне плеч.","Почувствуйте сокращение мышц на секунду и на вдохе начинайте опускать гантели обратно в исходное положение. Совет: При подъеме и опускании гантелей держите ладони обращенными вниз, а мизинцы чуть выше, так как это позволит сконцентрировать нагрузку в основном на плечах.","Повторите рекомендуемое количество повторений."],"fe_8c91cfbf":["Начните со штангой на полу. Гриф близко к голеням или касается их, хват широкий. Стопы прямо под тазом, носки развёрнуты по необходимости. Опустите таз, грудь поднята, взгляд вперёд. Плечи чуть впереди грифа. Это исходное положение.","Начните первый подъём, отталкиваясь передней частью пяток и отрывая штангу от пола. Угол наклона спины сохраняется, пока гриф не пройдёт колени.","Перейдите ко второму подъёму, разгибаясь в тазобедренных суставах, коленях и голеностопах и поднимая штангу как можно быстрее. Гриф должен двигаться близко к телу. В точке пикового разгибания выполните шраг плечами, позволяя локтям согнуться в стороны.","Переводя ноги в исходное положение, немного шире, подтягивайтесь под перекладиной, поднимая штангу над головой. Штангу следует принимать, частично приседая. Продолжайте поднимать штангу в исходное положение, принимая штангу зафиксированной над головой.","Вернитесь в положение стоя, держа вес тела над головой."],"fe_f222e2b6":["В «силовых ступенях» снаряды переносятся вверх по лестнице. Для тренировки подойдут шина или ящик.","Возьмите снаряд обеими руками. Поставьте стопы широко, голова и грудь подняты. Отталкиваясь пятками, разгибайте колени и тазобедренные суставы, поднимая вес с пола.","Отклоняясь назад, раскачайте вес на ступень — обычно высотой 40–45 см. Можно помочь ногами, толкая вес на ступень.","Повторите 3–5 раз и продолжайте с более тяжёлым весом, двигаясь как можно быстрее."],"fe_ffcee5f3":["Для выполнения этого упражнения вам понадобится партнер. Лягте лицом вниз, ноги выпрямлены. Ваш ассистент положит руку вам на пятку.","Для начала согните ногу в колене, чтобы согнуть ее вверх. Ваш партнер должен оказывать сопротивление, начиная с легкого движения и увеличивая давление по мере завершения движения. Общайтесь со своим партнером, чтобы контролировать соответствующие уровни сопротивления.","Задержитесь наверху, возвращая ногу в исходное положение, в то время как ваш партнер оказывает сопротивление, двигаясь в другую сторону."],"fe_55be5ac8":["Поставьте сани на подходящую поверхность, загрузив подходящий вес. Сопротивление должно требовать усилий, но не быть настолько тяжёлым, чтобы вы заметно замедлялись.","Используйте вертикальные или низкие рукояти. Возьмитесь за них выпрямленными руками, подавшись на снаряд вперёд.","С хорошей осанкой толкайтесь от земли короткими попеременными шагами. Двигайтесь как можно быстрее на короткой дистанции."],"fe_98668e49":["Примите упор лёжа на полу лицом вниз, кисти примерно на 90 см друг от друга, корпус поднят на выпрямленных руках.","Положите пальцы ног на мяч для упражнений. Это позволит вашему телу приподняться.","На вдохе опуститесь, пока грудь почти не коснётся пола.","Усилием грудных мышц выжмите корпус обратно в исходное положение и напрягите грудь. Выдохните во время этого шага.","После секундной паузы в сжатом положении повторите движение в течение предписанного количества повторений."],"fe_347b0bdb":["Начните с того, что наклоните туловище вперед на мяч так, чтобы ваши бедра опирались на мяч и становились самой высокой точкой вашего тела.","Положите руки и ступни на пол. Ваши руки и ноги могут быть слегка согнуты или выпрямлены, в зависимости от размера мяча, вашей гибкости и длины конечностей. Это также помогает развить силу стабилизации туловища и плеч."],"fe_84427ae0":["Лягте на пол лицом вниз, опираясь на руки или предплечья. Подложите под одну ногу на четырехглавую мышцу валик из пенопласта, не отрывая ступню от пола. Постарайтесь максимально расслабить ногу. Это будет ваше исходное положение.","Перенеся на растягиваемую ногу столько веса, сколько это возможно, перекатитесь по пенопласту от колена к бедру, удерживая точки натяжения в течение 10-30 секунд. Поменяйтесь сторонами."],"fe_67660445":["Для этого упражнения вам понадобится коробка.","Начните поворачиваться лицом к коробке, стоя в 1-2 футах от ее края.","Используя бедра, запрыгните на бокс, приземляясь на обе ноги. Убедитесь, что вы приземляетесь, согнув ноги и поставив ступни ровно.","Сразу после приземления полностью вытяните все тело и взмахните руками над головой, чтобы оттолкнуться от коробки. Используйте ноги, чтобы смягчить удар при приземлении."],"fe_963a25f6":["В этом упражнении вы научитесь поднимать штангу в стойку на плечах. Начните удерживать штангу в положении «чучело», когда плечи параллельны полу, а предплечья опущены вниз. Используйте захват крючком, обхватив большие пальцы руками.","Начните с вращения локтями вокруг штанги, доставляя штангу к плечам. Когда ваши локти выдвинутся вперед, ослабьте хватку. Плечи должны быть вытянуты вперед, образуя выступ для штанги, который должен слегка касаться горла.","Важно, чтобы штанга все время находилась близко к телу, так как при более тяжелой нагрузке любое расстояние может привести к нежелательному столкновению. По мере того как движение становится более плавным, скорость и нагрузку можно увеличивать, прежде чем двигаться дальше."],"fe_632a9a51":["Встаньте на четвереньки на коврике для упражнений. Ваша голова должна быть направлена вперед, а согнутые колени должны образовывать угол в 90 градусов между подколенными сухожилиями и икрами. Это будет ваше исходное положение.","Вытяните одну ногу вверх и заведите ее за спину. Колено и бедро должны быть вытянуты. Повторите 5-10 раз, а затем поменяйтесь сторонами."],"fe_d83d1357":["Для начала сядьте на велотренажёр и отрегулируйте седло под свой рост.","Выберите нужный режим в меню. Возможно, для включения придётся начать крутить педали. Доступен ручной режим или программа. Обычно можно ввести возраст и вес для оценки калорий. Уровень сопротивления можно менять во время тренировки. Рукояти могут измерять пульс, помогая держать нужную интенсивность.","Горизонтальный велотренажёр удобен, полезен для сердца и сосудов и даёт меньшую нагрузку на суставы, чем другие активности. Человек весом 68 кг сжигает около 230 калорий за 30 минут умеренного педалирования против 450 и более при беге."],"fe_be29439e":["Для этого упражнения вам понадобится напарник.","Начните с атлетической стойки на 2 или 3 точки.","По сигналу займите позицию для получения паса от вашего партнера.","Поймайте медицинский мяч обеими руками и немедленно бросьте его обратно своему партнеру.","Вы можете изменить это упражнение, выполнив различные маршруты."],"fe_69cdff41":["Установите штангу в стойку с электроприводом. Прикрепите ленты к верхней части стойки, используя либо колышки для лент, либо саму раму. Прикрепите другой конец лент к штанге.","Подойдите к перекладине так, чтобы она находилась по центру ваших ступней. Ваши ступни должны быть примерно на ширине бедер. Согнитесь в бедрах, чтобы обхватить перекладину на ширине плеч, позволяя лопаткам вытянуться. Как правило, в более тяжелых подходах вы используете хват сверху или снизу.","Выпрямив ноги и зафиксировав хватку, сделайте глубокий вдох, а затем опустите бедра и согните колени, пока голени не коснутся перекладины. Наклоните голову вперед, выпятите грудь и выгните спину дугой, а затем начните давить на пятки, чтобы переместить вес тела вверх.","После того как гриф пройдёт колени, энергично тяните его к себе, сводя лопатки и подавая таз вперёд к грифу.","Опустите штангу, наклоняясь в тазобедренных суставах и направляя её к полу."],"fe_cbe3f42f":["Начните с силовой стойки, установив штифты и планку на соответствующей высоте. После загрузки планки прикрепите ленты к верхней части стойки, используя либо колышки, либо саму раму. Прикрепите другой конец лент к планке.","Начните с того, что пройдите под перекладиной и положите ее на заднюю поверхность плеч. Сведите лопатки вместе и выдвиньте локти вперед, пытаясь согнуть штангу, перекинув ее через плечи. Снимите штангу со стойки, создавая плотную дугу в пояснице, и вернитесь в исходное положение. Расставьте ноги пошире, чтобы усилить нагрузку на спину, ягодичные мышцы, приводящие мышцы бедра и подколенные сухожилия.","Держите голову направленной вперед. Напрягите спину, плечи и ягодицы, раздвиньте колени и выпятите ягодицы и начинайте спуск. Откиньтесь назад, максимально выпрямив бедра. В идеале ваши голени должны быть перпендикулярны земле. Нижнее положение штанги требует большего наклона туловища, чтобы штанга находилась над пятками. Продолжайте, пока не нарушите параллельность, которая определяется как положение сгиба бедра на одной линии с верхней частью колена.","Держа вес на пятках и отводя стопы и колени в стороны, поднимайтесь вверх, ведя движение головой. Продолжайте, сохраняя напряжение от головы до пят, пока не вернётесь в исходное положение."],"fe_b27a1bdb":["Начните с того, что встаньте прямо, держа тарелку с утяжелителем обеими руками, полностью вытянув их вперед. Возьмите тарелку наклонным хватом (ладонями вниз) и следите за тем, чтобы пальцы хватались за шероховатую сторону тарелки, а большой палец — за гладкую. Примечание: Для достижения наилучших результатов возьмите утяжеленную пластину в положении «11:00» и «1:00:00».","Ваши ноги должны быть на ширине плеч, а утяжелитель должен находиться в области паха. Это исходное положение.","На выдохе медленно поднимите пластину вверх, не отрывая локтей от пола и не сгибая предплечья, пока ваши бицепсы и предплечья не соприкоснутся. В этот момент пластина должна находиться на одной линии с вашим туловищем.","Почувствуйте сокращение на секунду и на вдохе начинайте опускать вес обратно в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_e490e8fd":["Лягте на спину на плоскую скамью. Плотно прижав штангу к спине (примерно на ширине плеч), поднимите ее из стойки и держите прямо над собой, вытянув сцепленные руки перед собой перпендикулярно полу. Это будет ваше исходное положение.","На вдохе медленно опускайтесь, пока не почувствуете гриф у середины груди. Совет: в отличие от обычного жима лёжа, держите локти прижатыми к корпусу всё время, чтобы максимально включить трицепс.","После секундной паузы верните штангу в исходное положение на выдохе, выжимая её трицепсами. Зафиксируйте руки в сокращённом положении, задержитесь на секунду и снова начинайте медленно опускать. Совет: опускание должно занимать как минимум вдвое больше времени, чем подъём.","Повторите движение предписанное количество повторений.","По завершении верните штангу на стойки."],"fe_0aa41055":["Лягте спиной на пол. Подложите под верхнюю часть спины валик из пенопласта и скрестите руки перед собой, расправив плечи. Это будет ваше исходное положение.","Отрывайте бедра от пола, перенося вес тела на пенопластовый валик. Перемещайте вес тела поочередно на одну сторону, перекатываясь через середину и верхнюю часть спины. Задержитесь в точках напряжения на 10-30 секунд."],"fe_33d32439":["Поставьте раму в точку старта и загрузите подходящий вес. Встав в центре рамы, возьмитесь за рукояти и поднимите её, отталкиваясь пятками. Грудь и голова подняты, спина прямая.","Сразу начинайте идти быстрыми, короткими контролируемыми шагами. Держите грудь и взгляд вперёд и продолжайте дышать. Поставьте раму на землю по достижении финиша."],"fe_5e6a939d":["Загрузите раму нужным весом. Встаньте по центру между рукоятями. Стопы примерно на ширине таза. Наклонитесь в тазобедренных суставах и возьмитесь за рукояти, разводя лопатки.","Когда стопы и хват установлены, сделайте глубокий вдох, опустите таз и согните колени. Смотрите вперёд, грудь поднята, спина прогнута — начинайте тянуть вес вверх, отталкиваясь пятками. Когда вес идёт вверх, сводите лопатки, подавая таз вперёд.","Опустите вес, наклоняясь в тазобедренных суставах и направляя его к земле."],"fe_192b88dd":["Встаньте расслабленно, стопы на ширине плеч, руки близко к телу.","Чтобы начать движение, присядьте на корточки наполовину и снова поднимитесь как можно выше.","Полностью вытяните все тело, вытянув руки над головой как можно дальше. При приземлении амортизируйте удар ногами."],"fe_7463199e":["Начните стоять, держа штангу на вытянутых руках перед собой. Вы можете встать на приподнятую платформу, чтобы увеличить амплитуду движений.","Начните с того, что слегка согните ноги в коленях, а затем согнитесь в бедрах, отводя ягодицы как можно дальше назад и опуская туловище настолько, насколько позволяет гибкость. Спина должна оставаться полностью выпрямленной, а штанга должна оставаться в контакте с ногами. Если все сделано правильно, в подколенных сухожилиях должно ощущаться сильное напряжение.","Повторите движение в обратном направлении, чтобы вернуться в исходное положение."],"fe_6201158d":["Встаньте прямо, ноги вместе, держа в руках бодибар или метлу.","Держите шест за бедрами хватом шире, чем на ширине плеч. Ваши ладони должны быть опущены, а большие пальцы направлены наружу.","Медленно поднимите руки за голову. Не напрягайтесь, если вам будет трудно поднимать их дальше."],"fe_4d705453":["Для начала сядьте на гребной тренажёр. Убедитесь, что пятки удобно стоят на основании педалей и ремни зафиксированы. Выберите нужную программу, если она есть. Сядьте прямо и наклонитесь вперёд в тазобедренных суставах.","При работе на гребном тренажёре три фазы движения. Первая фаза — подъезд вперёд: колени согнуты и прижаты к груди, корпус слегка наклонён вперёд при сохранении хорошей осанки. Затем оттолкнитесь от педалей, разгибая ноги, и подтяните руки к верхней части живота, сводя плечи назад. Чтобы не перегрузить спину, работайте в основном ногами и мышцами таза.","Фаза восстановления — просто выпрямите руки, согните колени и снова подведите корпус вперёд, переходя в первую фазу."],"fe_d9630c6c":["Для заброса мешков с песком разложите снаряды на некотором удалении от помоста, обычно 15 метров.","Начните с подъёма мешка. Мешки крайне неудобны, и способ подъёма зависит от конкретного мешка. Обхватите его как можно дальше, разгибаясь в тазобедренных суставах и коленях, чтобы поднять высоко. Заброс на плечо обычно не разрешён.","Двигайтесь к помосту как можно быстрее и закиньте мешок, разгибаясь в тазобедренных суставах, коленях и голеностопах, чтобы поднять его как можно выше. Положите его на помост, следя, чтобы он не упал.","Вернитесь за следующим мешком и повторяйте, пока не завершите упражнение."],"fe_95b60a54":["Для начала лягте спиной на пол или на коврик для упражнений (по желанию). Руки должны быть полностью разведены в стороны ладонями вниз. Примечание: Руки должны быть неподвижны все время.","Слегка согнув ноги в коленях, поднимите их так, чтобы пятки находились примерно в 6 дюймах от земли. Это исходное положение.","Теперь поднимите левую ногу примерно под углом 45 градусов, в то время как правую опускайте так, чтобы пятка находилась примерно в 2-3 дюймах от земли.","Меняйте движения, поднимая правую ногу вверх и опуская левую. Не забывайте дышать во время выполнения этого упражнения.","Повторите рекомендуемое количество повторений."],"fe_32604a3c":["Закрепите ленту вплотную к земле и поставьте скамейку в паре футов от нее.","Сядьте на скамью и закрепите ремень за лодыжками, выпрямив ноги. Это будет ваше исходное положение.","Согните ноги в коленях, прижимая ступни к скамье. Возможно, вам придется слегка отклониться назад, чтобы ступни не касались пола.","Сделайте паузу по завершении движения, а затем медленно вернитесь в исходное положение."],"fe_d43cb9e4":["Сядьте на пол, согнув колени, а ваш партнер встаньте позади вас. Вытяните прямые руки за спину ладонями друг к другу. Ваш партнер будет держать вас за запястья. Это будет исходное положение.","Попытайтесь согнуть руки в локтях, в то время как ваш партнер препятствует какому-либо реальному движению.","Через 10-20 секунд расслабьте руки, в то время как ваш партнер мягко подтягивает ваши запястья вверх, чтобы растянуть бицепсы. Обязательно сообщите своему партнеру, когда растяжка уместна, чтобы предотвратить травму или перенапряжение."],"fe_0800acbf":["Сядьте на коврик, вытянув правую ногу перед собой, а левую согнув так, чтобы ступня была прижата к внутренней поверхности правого бедра.","Наклонитесь вперед от бедер и дотянитесь до лодыжки, пока не почувствуете растяжение подколенного сухожилия. Задержитесь на 15 секунд, затем повторите упражнение для другой стороны."],"fe_1eb79787":["Сядьте прямо на пол, ноги согнуты, партнер стоит позади вас. Разведите руки в стороны ладонями к полу. Постарайтесь отвести их как можно дальше за спину, так как ассистент держит вас за запястья. Это будет ваше исходное положение.","Держа локти прямыми, попытайтесь вытянуть руки вперед, при этом ваш партнер мягко удерживает вас, чтобы предотвратить любое реальное движение в течение 10-20 секунд.","Теперь расслабьте мышцы и позвольте партнеру слегка увеличить нагрузку на плечи и грудь. Задержитесь на 10-20 секунд."],"fe_39a52d65":["В положении сидя, с вытянутыми ногами, пусть ваш партнер встанет позади вас. Теперь наклонитесь вперед, а ваш партнер обхватит ваши плечи руками. Это будет ваше исходное положение.","Пытайтесь оттолкнуть корпус назад 10–20 секунд, пока партнёр не даёт ему двигаться.","Теперь расслабьтесь, пока партнёр усиливает растяжение, мягко надавливая на корпус 10–20 секунд."],"fe_a9d5426f":["Положите шейный ремень на пол в конце плоской скамьи. После того, как вы выбрали вес, сядьте на край плоской скамьи, расставив ноги шире, чем на ширину плеч. Пальцы ног должны быть направлены вперед.","Медленно наклоняйте туловище вперед, пока оно не станет почти параллельным полу. Обеими руками надежно закрепите шейный ремень вокруг головы. Совет: Убедитесь, что гантели по-прежнему лежат на полу, чтобы предотвратить нагрузку на шею. Теперь возьмите гирю обеими руками, одновременно поднимая туловище назад, пока оно не станет почти перпендикулярным полу. Примечание: Для выполнения этого упражнения ваша голова и туловище должны быть слегка наклонены вперед.","Теперь положите обе руки на колени. Это исходное положение.","На вдохе медленно опускайте шею вниз, пока подбородок не коснется верхней части груди.","На выдохе верните шею в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_867c1638":["Сядьте на скамью, вытянув ноги перед собой чуть ниже параллели, и держитесь за края скамьи. Корпус отклонён назад примерно на 45 градусов. Это исходное положение.","Подтяните колени к себе, одновременно приближая к ним корпус. Выдохните во время движения.","После секундной паузы вернитесь в исходное положение на вдохе.","Повторите рекомендуемое количество повторений."],"fe_cad94732":["Сядьте с прямой спиной на гимнастический коврик.","Соприкоснитесь подошвами ног так, чтобы ступни были на расстоянии шести-восьми дюймов от бедер.","Положите одну руку на пол рядом с собой, а другую — за голову.","Поднимите локоть к потолку, одновременно наклоняя туловище в другую сторону. Задержитесь на 10-20 секунд, затем поменяйте положение."],"fe_c2eeb1a6":["Держите штангу обеими руками ладонями вверх, кисти примерно на ширине плеч.","Поставьте стопы на пол чуть шире плеч.","Наклонитесь вперед и положите предплечья на верхнюю часть бедер ладонями вверх. Совет: Следите за тем, чтобы запястья лежали на коленях. Это будет ваше исходное положение.","На вдохе опустите штангу как можно ниже, крепко удерживая её.","Теперь на выдохе согните запястья, поднимая штангу как можно выше и напрягая предплечья. Задержите сокращение в верхней точке на секунду. Совет: двигается только запястье."],"fe_3d19177e":["Поставьте скамью перед тренажером с низким шкивом, на котором установлена штанга или приспособление для скручивания EZ.","Отодвиньте скамью достаточно далеко, чтобы, когда вы подносите ручку к верхней части бедер, на тросе создавалось натяжение из-за перемещения груза вверх.","Теперь возьмитесь за ручку обеими руками ладонями вверх, держа ее на ширине плеч.","Сделайте шаг назад и сядьте на скамью, ноги поставьте примерно на ширине плеч, твердо стоя на полу.","Наклонитесь вперед и положите предплечья на бедра, положив запястья тыльной стороной на колени. Это будет ваше исходное положение.","Опустите штангу как можно ниже, делая вдох и крепко сжимая ее.","Теперь поднимите штангу как можно выше, одновременно напрягая предплечья. Совет: Двигать следует только запястьями, но не предплечьями.","После второго сокращения в верхней точке на вдохе вернитесь в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_0efcbebf":["Возьмите по гантели в каждую руку и встаньте прямо.","Поднимите гантели на уровень груди/плеч, а затем поверните запястья так, чтобы ладони были обращены к вам, как если бы вы готовились выполнять жим Арнольда. Это будет ваше исходное положение.","Теперь начинайте вытягивать левую руку над головой, поворачивая запястье так, чтобы ладонь была направлена вперед, когда вы поднимаетесь. Ваши локти также должны выдвигаться вперед, когда вы поднимаете вес. Одновременно вы также будете сгибаться от бедра в противоположную сторону. Совет: Если вы выполняете упражнение правильно, это должно выглядеть так, как будто вы пытаетесь дотянуться до чего-то, находящегося над головой с правой стороны вашего тела, но левой рукой. При выполнении этого движения сделайте выдох.","Как только вы достигнете верхнего положения, сделайте вдох. Затем, полностью переместив вес тела над головой и наклонившись вправо, начните движение влево.","Повторите рекомендуемое количество повторений."],"fe_46da7cae":["Прикрепите одну ручку к низкому тросу.","После выбора правильного веса встаньте на пару футов назад, широко расставив ноги. Ваша рука должна быть вытянута, а плечо выдвинуто вперед. Это будет ваше исходное положение.","Выполняйте движение, втягивая плечо и сгибая локоть. При подтягивании сгибайте запястье, поворачивая ладонь вверх.","После короткой паузы вернитесь в исходное положение."],"fe_6c40b890":["Расслабив плечи и свободно расположив руки по бокам (или на коленях, если вы сидите), плавно двигайте плечами вперед, вверх, назад и вниз.","В обратном направлении. Вы можете выполнять это упражнение, чередуя движения плечами или обеими руками одновременно."],"fe_a6c217ae":["Расслабьте руки по бокам и поднимите плечи вверх к ушам, затем опустите их обратно."],"fe_480f1c55":["Вытяните левую руку вдоль тела и держите ее прямо."],"fe_727db046":["Встаньте сбоку от конуса или барьера.","Начните это упражнение с бокового прыжка через препятствие, отскакивая от места приземления, чтобы вернуться к тому месту, с которого вы начали.","Сделайте предписанное количество прыжков как можно быстрее и завершите упражнение, пробежав небольшое расстояние после выполнения последнего прыжка."],"fe_739fb414":["Начните с того, что лягте на правый бок и согните правое колено перед собой, чтобы стабилизировать положение туловища.","Положите голову на правую руку или плечо. Поднимите левую ногу вверх и держите ее за заднюю часть колена (так легче) или за ступню (труднее).","Подтяните левое колено к левому плечу и одновременно прижмите стопу или колено к полу. Чтобы усилить растяжку, выпрямите левую ногу. Поменяйтесь сторонами."],"fe_80573e7a":["Встаньте в спортивную стойку, расставив ноги на ширину бедер. Голова и грудная клетка должны быть приподняты, колени и бедра слегка согнуты. Это будет ваше исходное положение.","Наклоняясь вправо, вытяните бедра, колени и лодыжки, чтобы подпрыгнуть в воздух. Блокируйте движение руками, прыгая как можно дальше вправо.","Приземляйтесь лицом в том же направлении, расставив ноги на ширину бедер, поглощая удар нижней частью тела."],"fe_948050cb":["Встаньте сбоку от коробки, поставив левую ногу на ее середину.","Для начала подпрыгните вверх и перепрыгните на другую сторону коробки, приземлившись правой ногой на коробку, а левой — на пол. Размахивайте руками, чтобы облегчить движение.","Продолжайте передвигаться взад-вперед по коробке."],"fe_36ca8fed":["Поднимите блоки в верхнее положение, выберите сопротивление и возьмите по рукояти в каждую руку.","Встаньте перед обоими блоками, вытянув руки перед собой и сведя ладони вместе. Когда вы наклоняетесь вперед, ваша голова и грудная клетка должны быть приподняты, а ноги должны быть расставлены в шахматном порядке. Это будет ваше исходное положение.","Удерживая левую руку на месте, отведите правую руку в сторону, слегка согнув ее в локте. Правая рука должна быть перпендикулярна телу примерно на уровне плеча.","Верните руку в исходное положение, отведя ее назад к средней линии туловища.","Задержитесь на секунду в исходном положении и повторите движение с противоположной стороны. Продолжайте чередовать движения вперед и назад в течение предписанного количества повторений."],"fe_09a6a4b7":["Установите гриф в лендмайн или надёжно зафиксируйте его в углу. Навесьте подходящий вес.","Поднимите штангу от пола, взяв ее одной или обеими руками за плечи. Примите широкую стойку. Это будет ваше исходное положение.","Выполняйте движение, разгибая локоть и поднимая вес тела вверх. Двигайтесь стремительно, полностью разгибая бедра и колени, чтобы создать максимальную силу.","Вернитесь в исходное положение."],"fe_ac720d70":["Установите коробку на стойку. Закрепите над коробкой ленту или трос.","Встав перед ним, встаньте на ящик в положение полного стояния, оставив вторую ногу без опоры. Для равновесия держитесь за ленту.","Продолжайте переступать вверх-вниз на одной ноге, прежде чем перейти на противоположную сторону."],"fe_6b0b21e0":["Расположите перед собой ряд конусов. Примите расслабленное положение стоя, балансируя на одной ноге. Поднимите колено противоположной ноги. Это будет ваше исходное положение.","Прыгайте вперед, подпрыгивая и приземляясь той же ногой на конус.","Используйте прыжок с обратным движением, чтобы перепрыгивать с конуса на конус.","В конце повернитесь и вернитесь на другую ногу."],"fe_2398dba8":["Встаньте боком к тумбе, ближняя стопа на ней, у края.","Начните с маха руками вверх, отталкиваясь верхней ногой и выпрыгивая как можно выше. Стремитесь подтянуть противоположное колено вверх.","Приземляйтесь в том же положении, в котором вы начали, используя внутреннюю сторону ноги, чтобы замедлить удар."],"fe_497ddd39":["Стоя в широкой стойке, держите гантель обеими руками, ухватившись за головку гантели, а не за ручку. Ваши руки должны быть вытянуты и свисать на талии. Это будет ваше исходное положение.","Поднимайте вес до тех пор, пока он не окажется выше уровня плеч, держа руки вытянутыми. Ваш торс и бедра должны оставаться неподвижными на протяжении всего движения.","Вернитесь в исходное положение и повторите рекомендуемое количество раз."],"fe_0edd97fa":["Встаньте на землю, поставив одну ногу на ящик, пяткой близко к краю.","Оттолкнитесь ногой от верхней части ящика, стараясь набрать как можно больше высоты за счет разгибания бедра и колена.","Приземляйтесь той же ногой на верхнюю часть ящика, возвращая другую ногу в исходное положение."],"fe_b21c57e5":["Встаньте, поставив стопы на ширине плеч. Это исходное положение.","Начните движение, сгибая колени и тазобедренные суставы и отводя таз назад.","Продолжайте, пока не пройдете часть пути на корточках, но не окажетесь выше параллели, и быстро выполняйте обратные движения, пока не вернетесь в исходное положение. Повторите 5-10 раз."],"fe_5679dadc":["Роликовые коньки — весёлая активность, эффективно развивающая выносливость сердечно-сосудистой системы и мышц. Требуются неплохое равновесие и координация. Необходимо освоить основы катания, включая повороты и торможение, и надевать защиту, чтобы избежать травм.","Катайтесь в комфортном темпе 30 минут подряд. Для более серьёзной кардионагрузки делайте интервалы — две минуты из пяти катайтесь на скорости, оставшиеся три отдыхайте. Человек весом 68 кг сжигает около 175 калорий за 30 минут комфортного катания — как при быстрой ходьбе."],"fe_fc282087":["Для начала загрузите сани нужным весом и прикрепите тяговый ремень. Тянуть можно за рукояти, в упряжи или прикрепив ремень к поясу с весом.","Тянете ли вы вперёд или назад — наклоняйтесь в сторону движения и шагайте, разгибаясь в тазобедренных суставах и коленях."],"fe_4276887b":["Прикрепите две рукояти к саням, соединённым канатом или цепью. Нагрузите сани небольшим весом.","Встаньте лицом к саням, отступая назад, пока не почувствуете некоторое натяжение лески. Держите руки прямо над головой, согнув их в локтях. Это будет ваше исходное положение.","Двигайтесь задом наперед, держа руки поднятыми над головой. Избегайте резких движений."],"fe_b329a309":["Прикрепите к салазкам двойные ручки с помощью цепи или веревки. Установите на салазки соответствующую нагрузку.","Отвернувшись от саней, отступайте в сторону, пока линия не натянется. Поднимите руки над головой, держа их вместе, ладонями друг к другу. Локти должны быть согнуты и направлены вверх. Это будет ваше исходное положение.","Вытяните руку в локте, чтобы выпрямить ее. Следите за тем, чтобы верхняя часть руки оставалась в нужном положении, чтобы изолировать трицепсы.","После полного разгибания сделайте шаг вперед, чтобы ослабить натяжение лески. Для большей устойчивости вы можете расставлять ноги в шахматном порядке."],"fe_b0db9ee4":["Нагрузите свои сани-толкатели нужным весом.","Примите спортивную позу, опираясь на салазки, полностью вытянув руки и взявшись за ручки. Толкайте салазки как можно быстрее, сосредоточив внимание на разгибании бедер и коленей, чтобы укрепить заднюю цепь."],"fe_1ac473ae":["Прикрепите две рукояти к саням, соединённым канатом или цепью. Нагрузите сани небольшим весом.","Встаньте лицом к саням, отступая назад, пока леска не натянется. Возьмитесь за обе ручки на расстоянии вытянутых рук примерно на уровне талии. Слегка согните колени и поднимите грудь и голову. Это будет ваше исходное положение.","Не сгибая рук в локтях, потяните ручки вверх и в стороны, выполняя обратное движение с небольшим вращением наружу. При этом ваши ладони должны быть обращены вперед.","Вернитесь в исходное положение, сделав пару шагов назад, чтобы ослабить натяжение лески."],"fe_53f370cd":["Прикрепите две ручки к салазкам, соединенным веревкой или цепью. Установите салазки на соответствующий вес. Встаньте лицом к салазкам, отступая назад, пока трос не натянется.","Держа по ручке в каждой руке, слегка согните колени, поднимите голову и грудь и начните с вытянутых рук.","Чтобы начать движение, согните локоть и отведите лопатки назад, подтягивая салазки к себе.","Сделайте шаг или два назад, чтобы натянуть леску, и повторите упражнение."],"fe_c7c4afee":["Для этого упражнения вам понадобятся шина и кувалда. Встаньте перед шиной на расстоянии примерно двух футов от нее в шахматном порядке. Возьмите кувалду в руки.","Если вы правша, то ваша левая рука должна находиться внизу рукояти, а правая должна быть поднята ближе к головке.","Когда вы поднимаете кувалду, ваша правая рука скользит к головке; когда вы опускаетесь, ваша правая рука скользит вниз, присоединяясь к левой руке. Ударьте кувалдой как можно сильнее по шине. Контролируйте отскок кувалды от шины.","Повторите то же самое с другой стороны."],"fe_5ddadac2":["Расположите штангу на высоте колена и нагрузите ее соответствующим весом.","Возьмитесь за штангу руками, расположенными не на ширине плеч, и отцепите ее от тренажера. Руки должны быть полностью вытянуты, голова и грудь подняты. Локти должны быть направлены вперед, плечи отведены назад и опущены вниз. Ваши бедра должны быть отведены назад, создавая нагрузку на подколенные сухожилия. Это будет ваше исходное положение.","Начните движение с сильного разгибания бедер и коленей, ускоряясь при подъеме штанги. Убедитесь, что во время этой части движения вы держите руки прямыми.","После полного разгибания снова согните бедра и колени, чтобы опуститься в исходное положение.","В этот момент позвольте рукам согнуться, вращая локтями вокруг штанги, чтобы она легла вам на плечи.","Вытянитесь за счет бедер и коленей, чтобы принять положение стоя со штангой на плечах для завершения движения."],"fe_3ffcd6ca":["Установите гриф в тренажёре Смитта на высоте примерно середины бедра. Когда высота выбрана и вес навешен, возьмитесь за гриф пронированным хватом (ладони вперёд) на ширине плеч. При большом весе могут понадобиться бинты на запястья.","Поднимите штангу, полностью выпрямив руки, сохраняя при этом спину прямой. Встаньте, выпрямив туловище и расставив ноги на ширину плеч или более узкую стойку. Колени должны быть слегка согнуты. Это ваше исходное положение.","Удерживая колени неподвижными, опустите штангу на верхнюю часть ступней, сгибаясь в талии и сохраняя спину прямой. Продолжайте двигаться вперед, как будто собираетесь поднять что-то с пола, пока не почувствуете растяжение подколенных сухожилий. Выполняя это движение, выдохните.","Как только почувствуете, что подколенные сухожилия растягиваются, снова выпрямляйте туловище, разгибая бедра и талию, пока не вернетесь в исходное положение. Выполняя это движение, сделайте вдох.","Повторите рекомендуемое количество повторений."],"fe_cf79d00d":["Поставьте ноги на ширину плеч так, чтобы штанга находилась прямо над местом соединения пальцев ног с остальной частью стопы.","Возьмитесь за перекладину хватом ладонями вниз, согните ноги в коленях и, держа спину ровно, возьмитесь за перекладину хватом шире, чем на ширине плеч. Опустите бедра и убедитесь, что ваше тело опустилось, как будто вы собираетесь сесть на стул. Это будет ваше исходное положение.","Начните отталкиваться ногами от пола, как если бы это была движущаяся платформа, и одновременно начинайте поднимать штангу, держа ее как можно ближе к ногам.","Когда штанга достигнет середины ваших бедер, оттолкнитесь ногами от пола и взрывным движением поднимите туловище до полного разгибания.","Отведите плечи назад, пожимая плечами, когда поднимаете штангу, одновременно разводя локти в стороны и удерживая их над перекладиной как можно дольше.","Теперь очень быстрым, но мощным движением вы должны подвести свое тело под штангу, когда она поднимется достаточно высоко, чтобы ее можно было контролировать, и опустить, сцепив руки и держа штангу над головой, когда вы принимаете положение приседа.","Завершите движение, поднимаясь из положения приседа, чтобы завершить подъем. В конце подъема обе ноги должны быть на одной линии, а руки должны быть полностью вытянуты, удерживая штангу над головой."],"fe_0aa5476a":["Начните с того, что поставьте ноги в положение подтягивания, положите штангу на заднюю поверхность плеч, а руки разведите широким хватом.","Оттолкнитесь от перекладины резким опусканием и движением коленей, а затем агрессивно пройдите под перекладиной, переводя стопы в исходное положение.","Поднимите штангу над головой в нижней части приседа. Туловище должно оставаться вертикальным, бедра должны быть опущены между ног.","Продолжайте опускаться на полную глубину и вернитесь в положение стоя. Осторожно опустите вес."],"fe_e9e581b0":["Становая тяга в рывке усиливает первый прием рывка. Начните с выполнения рывка широким хватом со штангой, расположенной на платформе. Ступни должны находиться прямо под бедрами, стопы должны быть развернуты наружу. Присядьте на корточки перед перекладиной, держа спину полностью выпрямленной, а голову направленной вперед.","Начните движение с движения пятками, приподнимая бедра. Угол наклона спины должен оставаться неизменным до тех пор, пока штанга не пройдет над коленями.","В этот момент, лежа на спине, проведите бедрами по перекладине. Верните штангу на платформу, сделав движение в обратном направлении."],"fe_c44b1b2c":["Начните с широкого хвата, при этом штанга должна висеть на уровне середины бедра. Вы можете использовать крюк или хват сверху вниз. Ваша спина должна быть прямой и слегка наклонена вперед.","Подтяните плечи к ушам. Хотя в этом упражнении обычно используется больший вес, чем в рывке, избегайте перегрузки до такой степени, что выполнение замедлится."],"fe_2b8bb082":["Начните со штангой на ящиках или стойках нужной высоты. Хват широкий. Стопы прямо под тазом, носки развёрнуты по необходимости. Опустите таз, грудь поднята, взгляд вперёд. Плечи чуть впереди грифа, локти развёрнуты в стороны. Это исходное положение.","Начните первый подъём, отталкиваясь передней частью пяток и отрывая штангу от ящиков.","Перейдите ко второму подъёму, разгибаясь в тазобедренных суставах, коленях и голеностопах и поднимая штангу как можно быстрее. Гриф должен двигаться близко к телу. В точке пикового разгибания выполните шраг плечами, позволяя локтям согнуться в стороны.","Переводя ноги в исходное положение, с усилием подтягивайтесь под перекладину, поднимая ее над головой. Ступни должны находиться на уровне бедер, при необходимости вывернутые наружу. Примите штангу, наклонившись как можно ниже и полностью вытянув руки над головой.","Держа гриф над передней частью пяток, голову и грудь поднятыми, отталкивайтесь пятками, вставая в полный рост. Аккуратно верните штангу на ящики."],"fe_806d55f5":["Для выполнения этого упражнения прикрепите ленту к земле. Мы использовали наклонную скамью и прикрепили ленту к основанию, стоя над скамьей. В качестве альтернативы, это упражнение можно выполнять стоя на ленте.","Для начала заведите резинку за голову, удерживая ее вытянутым хватом и подняв локти вверх. Это будет ваше исходное положение.","Чтобы выполнить это движение, вытяните руки в локтях и выпрямите их, следя за тем, чтобы верхняя часть предплечья оставалась на месте.","Сделайте паузу, а затем вернитесь в исходное положение."],"fe_db8f2c8e":["Сядьте на стул так, чтобы ваша спина была прямой, а ноги стояли на полу.","Переплетите пальцы за головой, разведите локти в стороны и опустите подбородок.","Поверните верхнюю часть туловища в одну сторону примерно 3 раза, насколько сможете. Затем наклонитесь вперед и поверните туловище так, чтобы коснуться локтем пола с внутренней стороны колена.","Вернитесь в вертикальное положение, а затем повторите упражнение для другого бока."],"fe_f2e0efe3":["Поставив штангу на пол рядом с голенями, возьмитесь за нее хватом сверху, чуть выше ног. Опустите бедра, сосредоточив вес на пятках, спина прямая, голова направлена вперед, грудь приподнята, плечи находятся прямо перед перекладиной. Это будет ваша исходная позиция.","Начните первый подъём, отталкиваясь пятками и разгибая колени. Угол наклона спины должен сохраняться, руки — оставаться прямыми. Поднимайте вес подконтрольно, пока гриф не пройдёт колени.","Далее следует второй подъём — главный источник ускорения во взятии. Когда гриф приближается к середине бедра, начинайте разгибаться в тазобедренных суставах. Прыжковым движением ускоряйте штангу вверх, разгибая тазобедренные суставы, колени и голеностопы. Активно тянуть руками не нужно: в конце второго подъёма тело полностью выпрямлено и слегка отклонено назад, руки всё ещё прямые.","Когда вы достигнете полного разгибания, переходите к третьему подтягиванию, энергично пожимая плечами и сгибая руки в локтях вверх и в стороны. При максимальном разгибании энергично опускайтесь вниз, вращая локтями под перекладиной.","Примите штангу, расставив ноги, энергично двигая одну ногу вперед, а другую назад. Штангу следует положить на вытянутые плечи, слегка касаясь горла расслабленными руками. Продолжайте опускаться в нижнее положение, которое поможет в восстановлении.","Немедленно восстановите равновесие, сделав движение пятками, держа туловище прямо, а локти поднятыми. При вставании сведите ступни вместе."],"fe_92691bbd":["Стоя, перенеся вес тела на переднюю поверхность плеч, начните с опускания. Расположив ступни прямо под бедрами, согните колени, не отводя бедра назад.","Опускайтесь совсем чуть-чуть и как можно сильнее меняйте направление движения. Вращайте пятками, создавая как можно большую скорость и усилие, и обязательно отводите голову в сторону, когда штанга покидает плечи. В этот момент, когда ступни отрываются от пола, их необходимо как можно быстрее поставить в исходное положение.","В тот короткий момент, когда ступни не будут активно упираться в платформу, усилие спортсмена, направленное на поднятие штанги, приведет к их опусканию. Ноги следует перевести в раздвоенную стойку, одна нога вперед, другая назад, колени частично согнуты. Примите штангу так, чтобы руки были вытянуты над головой.","Вернитесь в положение стоя, сведя ступни вместе."],"fe_002781c5":["Примите положение выпада: одна нога впереди с согнутым коленом, заднее колено почти касается пола.","Следите за тем, чтобы переднее колено находилось над средней линией стопы.","Вытягиваясь на обеих ногах, подпрыгните как можно выше, размахивая руками, чтобы увеличить подъемную силу.","Когда вы прыгаете, сведите ноги вместе и верните их в исходное положение при приземлении.","Смягчите удар, вернувшись в исходное положение."],"fe_86c8b0dc":["Начните со штангой на полу. Гриф близко к голеням или касается их, хват широкий. Стопы прямо под тазом, носки развёрнуты по необходимости. Опустите таз, грудь поднята, взгляд вперёд. Плечи чуть впереди грифа. Это исходное положение.","Начните первый подъём, отталкиваясь передней частью пяток и отрывая штангу от пола. Угол наклона спины сохраняется, пока гриф не пройдёт колени.","Перейдите ко второму подъёму, разгибаясь в тазобедренных суставах, коленях и голеностопах и поднимая штангу как можно быстрее. Гриф должен двигаться близко к телу. В точке пикового разгибания выполните шраг плечами, позволяя локтям согнуться в стороны.","Переводя ноги в исходное положение, с усилием подтягивайтесь под перекладину, поднимая ее над головой. Ноги должны с усилием перемещаться в положение раздвоения, одна нога вперед, другая назад. Примите штангу, наклонившись как можно ниже и полностью вытянув руки над головой.","Держа штангу на одной линии с передней частью пяток, а голову и грудь приподнятыми, пройдитесь по пяткам ног, чтобы перейти в положение стоя, сведя ступни вместе.","Осторожно верните груз на пол."],"fe_af67e792":["Для установки цепей накиньте направляющую цепь на втулки грифа. Тяжёлая цепь крепится карабином. Подберите длину направляющей цепи так, чтобы в верхней точке движения несколько звеньев ещё лежали на полу.","Встаньте под гриф и положите его на заднюю часть плеч. Сведите лопатки и разверните локти вперёд, как бы сгибая гриф на плечах. Снимите штангу со стоек, жёстко прогнув поясницу, и отшагните в позицию. Поставьте ноги широко, чтобы сместить акцент на спину, ягодицы, приводящие мышцы и бицепсы бедра. Держите голову, глядя вперёд.","Держа спину, плечи и корпус в напряжении, отводите колени и таз назад, начиная опускаться. Отводите таз назад максимально. В идеале голени перпендикулярны полу. Низкое положение грифа требует большего наклона корпуса, чтобы держать штангу над пятками. Опускайтесь ниже параллели — когда складка тазобедренного сустава на уровне верха колена.","Держа вес на пятках и отводя стопы и колени в стороны, поднимайтесь вверх, ведя движение головой. Продолжайте, сохраняя напряжение от головы до пят, пока не вернётесь в исходное положение."],"fe_2fd0ed7e":["Для начала установите штангу на стойку так, чтобы она была чуть ниже уровня плеч. Поставьте утяжелитель на пол в паре футов от стойки. Как только штанга будет нагружена, встаньте под нее и положите на нее заднюю часть плеч.","Возьмитесь за перекладину обеими руками и поднимите ее со стойки, сначала оттолкнувшись ногами и одновременно выпрямив туловище.","Отойдите от стойки и примите широкую стойку, слегка расставив пальцы ног, поставив одну ногу на штангу с отягощением. Все время держите голову высоко поднятой. Это будет ваше исходное положение.","Начинайте медленно опускать штангу, сгибая колени и бедра. Продолжайте опускаться, пока угол между верхней частью ноги и икрами не станет чуть меньше 90 градусов.","Поднимите штангу на выдохе, отталкиваясь от пола пятками ног и разгибая бедра и колени.","В конце движения сделайте шаг в сторону, сведя ноги вместе на противоположной стороне тарелки.","Внутренней стороной стопы надавите на утяжелитель, перемещая его по полу туда, где вы только что стояли.","Поставьте внутреннюю сторону стопы на утяжелитель, приняв широкую стойку для следующего повторения."],"fe_e9921cee":["Заведите руки за спину ладонями вместе, выпрямите их, а затем поверните так, чтобы ладони были обращены вниз.","Поднимите руки вверх и удерживайте их, пока не почувствуете растяжение в бицепсах."],"fe_1a815e46":["Расположите два блока на высоте груди и выберите подходящий вес. Встаньте на расстоянии одного-двух футов от тросов, держа по одному в каждой руке. Для большей устойчивости вы можете покачиваться в своей стойке.","Расположите предплечье под углом 90 градусов так, чтобы лопатки были вместе. Это будет ваше исходное положение.","Удерживая остальную часть тела неподвижной, вытяните руки в локтях вперед и сведите их вместе перед собой.","Сделайте паузу в верхней точке движения и вернитесь в исходное положение."],"fe_1505efd0":["Подсоедините стандартную рукоятку к башне и переместите трос в самое верхнее положение шкива.","Встаньте боком к блоку, возьмите рукоять одной рукой и отойдите от тренажёра. Вы должны быть примерно на длину руки от блока, с натянутым тросом. Вытянутая рука — на одной линии с тросом.","Расставив ноги на ширину плеч, вытяните другую руку вверх и возьмитесь за ручку обеими руками. Ваши руки по-прежнему должны быть полностью вытянуты.","Одним движением потяните рукоятку вниз и через все тело к переднему колену, одновременно поворачивая туловище.","Держите спину и руки прямыми, а корпус напряженным, одновременно поворачивая заднюю ногу и сгибая колени, чтобы получить полный диапазон движений.","Сохраняйте стойку и прямые руки. Медленно и контролируемо вернитесь в нейтральное положение.","Повторяйте до отказа.","Затем повторите ту же серию движений на противоположной стороне."],"fe_cc5e6b72":["Начните с того, что встаньте спиной примерно в двух-трех футах от скамьи или ступеньки.","Заведите одну ногу за спину и поставьте ступню на ступеньку, либо на подъем, либо на подушечку стопы, в зависимости от того, что вам кажется наиболее удобным.","Держите опорное колено слегка согнутым и не допускайте, чтобы оно выступало за пределы пальцев ног. Поменяйтесь сторонами."],"fe_6a9deac0":["Начните стоять на одной ноге, держась за вертикальную опору.","Поднимите колено без опоры на 90 градусов. Это будет ваше исходное положение.","Разведите бедро как можно шире, стараясь сделать коленом большой круг.","Выполните это движение медленно в течение нескольких повторений и повторите с другой стороны."],"fe_208fbae1":["Встаньте прямо, держа позвоночник вертикально, левая нога немного впереди правой.","Согните оба колена и оторвите заднюю пятку от пола, одновременно выдвигая правое бедро вперед. Однако в этом положении вы не сможете выполнить полную и глубокую растяжку, поскольку трудно одновременно расслабить сгибатель бедра и стоять на нем. Поменяйтесь сторонами."],"fe_04d51221":["Отрегулируйте рычаг тренажера в соответствии со своим ростом и лягте так, чтобы туловище было согнуто в талии и обращено вперед примерно на 30-45 градусов (так как наклонное положение более благоприятно для развития подколенных сухожилий), а подушечка рычага находилась на задней поверхности правой ноги (всего в нескольких дюймах под икрами), а передняя часть поставьте правую ногу поверх рабочей площадки станка.","Держа туловище наклоненным вперед, убедитесь, что ваша нога полностью вытянута, и возьмитесь за боковые ручки тренажера. Выпрямите пальцы ног. Это будет ваше исходное положение.","На выдохе согните правую ногу как можно выше, не отрывая ее от подушки. Как только вы достигнете полностью согнутого положения, задержитесь в нем на секунду.","На вдохе верните ноги в исходное положение. Повторите рекомендуемое количество повторений.","Теперь выполните то же упражнение для левой ноги."],"fe_dba3ec42":["Начните с того, что встаньте справа от ряда нижних шкивов. Проведите левой рукой вдоль тела и возьмитесь за единственную ручку, прикрепленную к нижнему шкиву, наклонным хватом (ладонями вниз). Вытяните руки перед собой. Вашей правой рукой следует обхватить тренажер для лучшей поддержки и равновесия.","Следите за тем, чтобы ваша спина была прямой, а ноги находились на ширине плеч. Это исходное положение.","Начните использовать левую руку и на выдохе двигайте ею поперек туловища до тех пор, пока она не поднимется на высоту плеча.","На секунду почувствуйте сжатие в верхней части и на вдохе начинайте медленно опускать рукоятку обратно в исходное положение.","Повторите рекомендуемое количество повторений.","Смените руку и повторите упражнение."],"fe_2792e209":["Начните с того, что встаньте прямо и держите штангу за ягодицами на расстоянии вытянутой руки, используя прямой хват (ладони должны быть обращены назад от ягодиц), а руки должны быть на ширине плеч друг от друга.","Вы должны смотреть прямо перед собой, а ваши ноги должны быть на ширине плеч. Это исходное положение.","На выдохе медленно поднимите штангу вверх, совершая полукруглые движения запястьем по направлению к потолку. Примечание: В этом упражнении должно двигаться только запястье.","Задержите сжатие на секунду и на вдохе опустите штангу обратно в исходное положение.","Повторите рекомендуемое количество повторений.","Когда закончите, опустите штангу на стойку для приседаний или на пол, согнув ноги в коленях. Совет: Проще всего либо поднять ее из стойки для приседаний, либо попросить партнера подать ее вам."],"fe_f0962113":["Встаньте так, чтобы ноги были на расстоянии бедер друг от друга, одна ступня была немного впереди другой.","Согните оба колена, не отрывая пятки от пола. Поменяйтесь сторонами."],"fe_d40cf4a5":["Встаньте так, чтобы ноги были на ширине плеч, держа в обеих руках медицинский мяч. Для начала заведите медицинский мяч глубоко за голову, слегка согнув колени и откинувшись назад.","Резко выбросьте мяч вперед, сгибаясь в бедрах и используя все свое тело для завершения движения.","Медицинский мяч можно бросить партнеру или в стену, получив его, когда он отскочит назад."],"fe_e1a85370":["Встаньте лицом к ящику или скамье соответствующей высоты, ноги вместе. Это будет ваше исходное положение.","Начните движение с того, что сделайте шаг вперед и поставьте левую ногу на край скамьи. Вытяните бедро и колено передней ноги, чтобы встать на ящик. Стоя на ящике левой ногой, согните правое колено и бедро, поднимая колено как можно выше.","Повторите это движение в обратном направлении, чтобы спуститься с ящика, а затем повторите упражнение на противоположной ноге."],"fe_b9e20b65":["Для начала встаньте прямо, ноги на ширине плеч. Положите руки на бедра. Это исходное положение.","Теперь медленно вдохните как можно больше воздуха, а затем начните выдыхать как можно больше, максимально втягивая живот, и удерживайте это положение. Попробуйте представить, что ваш пупок касается позвоночника.","Одно изометрическое сокращение длится около 20 секунд. Во время 20-секундной задержки старайтесь дышать нормально. Затем сделайте вдох и верните живот в исходное положение.","После того, как вы освоите это упражнение, попробуйте выполнять его дольше 20 секунд. Совет: Вы можете увеличить время выполнения до 40-60 секунд.","Повторите упражнение рекомендуемое количество раз."],"fe_1cef0e2c":["Положите нагруженную штангу на край скамьи. Стоя на скамье за перекладиной, возьмитесь за нее средним хватом. Отведите бедра назад и поднимите грудь, сохраняя нейтральное положение позвоночника. Это будет ваше исходное положение.","Подтяните штангу к туловищу, втягивая лопатки и сгибая руки в локтях. Выполняйте контролируемые движения без рывков.","После короткой паузы медленно верните штангу в исходное положение, стараясь опустить ее до конца."],"fe_9cefc74c":["Положите штангу на пол за изголовьем наклонной скамьи.","Лягте на скамью лицом вниз. Выпрямленным хватом поднимите штангу с пола, держа руки прямыми. Пусть штанга свисает вертикально вниз. Это будет ваше исходное положение.","Для начала поднимите штангу перед головой, держа руки вытянутыми.","Вернитесь в исходное положение."],"fe_a53049d0":["Встаньте боком к тумбе, ближняя стопа на ней, у края.","Начните с маха руками вверх, отталкиваясь верхней ногой и выпрыгивая как можно выше. Стремитесь подтянуть противоположное колено вверх.","Приземляйтесь в положении, противоположном тому, в котором вы начинали, на противоположной стороне ящика. Нога, которая изначально стояла на ящике, теперь будет на земле, а противоположная нога — на ящике.","Повторите это движение, снова переходя на другую сторону."],"fe_56b13a36":["Для начала лягте прямо лицом вниз на пол или коврик для упражнений. Ваши руки должны быть полностью вытянуты перед собой. Это исходное положение.","Одновременно поднимите руки, ноги и грудную клетку от пола и удерживайте это сжатие в течение 2 секунд. Совет: Напрягите нижнюю часть спины, чтобы добиться наилучших результатов от этого упражнения. Не забывайте делать выдох во время выполнения этого движения. Примечание: Находясь в сжатом положении, вы должны выглядеть как супермен в полете.","На вдохе начинайте медленно опускать руки, ноги и грудную клетку обратно в исходное положение.","Повторите рекомендуемое программой количество повторений."],"fe_25fe4647":["Лягте на спину, согнув колени. Держите мяч одной рукой, полностью заведя ее за голову. Это будет ваше исходное положение.","Начните движение от плеча, бросая мяч прямо перед собой, поднимая корпус, — на максимальную дальность.","Мяч можно бросать партнёру или об стену."],"fe_2bfb85d5":["Установите гриф в лендмайн или в угол, чтобы он не двигался. Навесьте подходящий вес на ваш конец.","Встаньте над перекладиной и закрепите двойную ручку в виде буквы D вокруг перекладины рядом с воротником. Используя бедра и ноги, поднимитесь в положение стоя.","Примите широкую стойку, отведя бедра назад и выпятив грудь. Ваши руки должны быть вытянуты. Это будет ваше исходное положение.","Подтяните вес к верхней части живота, втягивая лопатки и сгибая локти. Не делайте резких движений весом и не жульничайте во время движения.","После короткой паузы вернитесь в исходное положение."],"fe_58e661ba":["Начните с вертикального положения сидя. Для начала вытяните ноги перед собой в виде буквы V.","Упритесь руками в пол и наклонитесь вперед как можно дальше. Задержитесь на 10-20 секунд."],"fe_2b02231f":["Лягте на пол или гимнастический коврик, прижав спину к полу. Руки вдоль корпуса ладонями вниз.","Ваши ноги должны касаться друг друга. Медленно поднимайте ноги в воздух, пока они не станут почти перпендикулярны полу, слегка согнув их в коленях. Ступни должны быть параллельны полу.","Поднимите руки так, чтобы они были полностью вытянуты и находились под углом 45 градусов к полу. Это исходное положение.","Прижимая поясницу к полу, медленно поднимите туловище и попытайтесь руками коснуться пальцев ног. Не забывайте делать выдох во время выполнения этой части упражнения.","На вдохе начинайте медленно опускать туловище и руки обратно в исходное положение. Помните, что руки должны быть выпрямлены и направлены к носкам.","Повторите рекомендуемое количество повторений."],"fe_2f089211":["Встаньте прямо, держа мяч для упражнений обеими руками. Вытяните руки так, чтобы мяч был прямо перед вами. Это будет ваше исходное положение.","Поверните туловище в одну сторону, не отрывая взгляда от мяча. Теперь повернитесь в противоположную сторону. Повторите 10-20 раз."],"fe_57cf0633":["Сидя, наклонитесь вперед и обхватите бедра снизу обеими руками.","Держите колени вместе, а ноги вытянутыми в стороны, прижимая грудь к коленям. Вы также можете растянуть поясницу, отрывая спину от коленей и обхватывая их руками."],"fe_2b220bd7":["Для начала встаньте на тренажерную ленту так, чтобы натяжение начиналось на расстоянии вытянутой руки. Возьмитесь за ручки, используя пронированный захват (ладони обращены к бедрам), который должен быть чуть меньше ширины плеч. Ручки должны находиться на верхней части бедер. Ваши руки должны быть вытянуты вперед, слегка согнуты в локтях, а спина должна быть прямой. Это будет ваше исходное положение.","На выдохе поднимайте ручки, опираясь на плечи. При движении вверх ручки должны быть прижаты к телу. Продолжайте поднимать ручки, пока они почти не коснутся вашего подбородка. Совет: Локти должны направлять движение. Когда вы поднимаете ручки, ваши локти всегда должны быть выше предплечий. Кроме того, держите туловище неподвижно и сделайте секундную паузу в начале движения.","Медленно верните рукояти в исходное положение. Вдыхайте во время этой фазы движения.","Повторите рекомендуемое количество повторений."],"fe_50347d50":["Вытяните обе руки прямо над головой, соприкасаясь ладонями.","Медленно поднимите руки вверх и назад, держа спину прямой."],"fe_742b4a69":["Начните с того, что поместите середину V-образной перекладины в середину подтягивающей штанги (при условии, что на используемом вами станке для подтягивания нет ручек с нейтральным захватом). Ручки V-образной планки будут обращены вниз, чтобы вы могли свисать с выдвижной планки с помощью ручек.","Как только вы надежно закрепите планку, возьмитесь за нее с каждой стороны и повисните на ней. Выпятите грудь и слегка отклонитесь назад, чтобы лучше задействовать широчайшие мышцы. Это будет ваше исходное положение.","Используя свои широкие мышцы, подтяните туловище вверх, слегка откидывая голову назад, чтобы не удариться о перекладину для подбородка. Продолжайте, пока ваша грудь почти не коснется перекладины. При выполнении этого движения выдохните.","Задержавшись на секунду в сжатом положении, на вдохе медленно опустите тело обратно в исходное положение.","Повторите предписанное количество повторений."],"fe_f6fba75b":["Держите гантель обеими руками так, чтобы она висела между ног на расстоянии вытянутых рук. Держите спину прямо, а голову высоко поднятой.","Зажмите гантель между ног, сгибая их в бедрах и слегка сгибая колени.","Выполните мощное обратное движение, разгибаясь в бедрах, коленях и лодыжках, чтобы приподняться вверх и поднять гантель над головой.","Приземляясь, амортизируйте удар ногами и подтяните гантель к туловищу перед следующим повторением."],"fe_689c9fb3":["Для начала лягте на гимнастический мяч так, чтобы ваш торс был прижат к мячу и параллелен полу. Подушечки ваших стоп должны быть прижаты к полу, чтобы вы могли сохранять равновесие. Положите утяжелитель под подбородок или за шею. Это исходное положение.","Медленно поднимите туловище вверх, прогибаясь в талии и пояснице. Не забывайте делать выдох во время этого движения.","Задержите напряжение в нижней части спины на секунду и на вдохе опустите туловище обратно в исходное положение.","Повторите рекомендуемое программой количество повторений."],"fe_8119824a":["Для начала лягте на гимнастический мяч так, чтобы левая сторона туловища (талия, бедра и плечо) была прижата к мячу.","Ваши ступни должны находиться на полу, а ноги скрещены и свисают с мяча. Поднесите утяжеленную тарелку правой рукой прямо к правой стороне головы. Совет: Убедитесь, что гладкая сторона тарелки прилегает к вашей голове.","Положите левую руку поперек туловища так, чтобы ладонь лежала на косых мышцах живота. Между левым предплечьем и плечом должен быть прямой угол. Это исходное положение.","На выдохе поднимите боковую часть туловища вверх, прогибаясь в талии вбок.","Задержите сжатие на секунду и на вдохе медленно опустите себя обратно в исходное положение.","Повторите рекомендуемое количество повторений.","Поменяйтесь сторонами и повторите упражнение."],"fe_31b14764":["Начните с закрепления лент вокруг основания откидной скамьи. Расположите ручки с внутренней стороны откидной скамьи так, чтобы, лежа, вы могли дотянуться до них обеих.","Расположите ноги на тренажере так, чтобы они были надежно закреплены. Теперь возьмитесь за тренажерные ленты обеими руками. Возьмитесь за ручки наклонным хватом (ладонями вперед). Расположите их рядом с ключицами и поверните запястья нейтральным хватом (ладони обращены к туловищу). Примечание: Ваши руки должны оставаться неподвижными на протяжении всего упражнения. Это исходное положение.","На выдохе поднимите туловище вверх, пока верхняя часть тела не окажется перпендикулярной полу. Задержите сжатие на секунду и на вдохе опустите верхнюю часть тела обратно в исходное положение.","Повторите рекомендуемое количество повторений."],"fe_05a78a6f":["Начните со штанги, поставленной на пол. Примите широкую стойку, а затем прогнитесь в бедрах, чтобы ухватиться за перекладину. Ваши бедра должны быть отведены как можно дальше назад, ноги должны быть почти прямыми. Держите спину прямо, а голову и грудь приподнятыми. Это будет ваша исходная позиция.","Начните движение, задействуя бедра, двигая их вперед, позволяя рукам висеть прямо. Продолжайте, пока не встанете прямо, а затем медленно верните вес в исходное положение. При выполнении последовательных повторений вес не должен касаться пола."],"fe_850c44b5":["Лягте на спину, руки разведите в стороны, ноги выпрямите. Это будет ваше исходное положение.","Поднимите одну ногу и быстро перекиньте ее через туловище, стараясь коснуться земли рядом с противоположной рукой.","Вернитесь в исходное положение и повторите упражнение с противоположной ногой. Продолжайте чередовать 10-20 повторений."],"fe_e19751d6":["Возьмите штангу обеими руками ладонями вниз, расставив руки примерно на ширину плеч. Это будет ваше исходное положение.","Чередуя движения каждой рукой, выполняйте их, разгибая запястье, как если бы вы сворачивали газету. Продолжайте чередовать движения вперед и назад до отказа.","Повторите движение в обратном направлении, сгибая запястье и поворачивая его в противоположном направлении. Продолжайте чередовать движения до отказа."],"fe_602efec2":["Сгибание обычно выполняется с помощью специального приспособления, но иногда его можно увидеть с помощью холодильников или других тяжелых предметов.","Начните с того, что закрепите тренажер на задней поверхности плеч. Повернув голову вперед и выгнув спину дугой, поднимите хомут, надавливая на пятки.","Начинайте ходить как можно быстрее, используя короткие шаги. Вы можете держаться за боковые стойки коромысла, чтобы оно было устойчивым и удерживало его в нужном положении. Пройдите заданное расстояние как можно быстрее, обычно это 75-100 футов."]}
